import { KeywordDistillationPage } from '../../features/keyword-distillation'

const Dashboard = lazy(() => import('../../Dashboard'))
type IconType = typeof LayoutDashboard




function App() {
  const [storedState, setStoredState] = usePersistentState<AppState>(STORAGE_KEY, defaultAppState, normalizeState)
  const state = useMemo(() => normalizeState(storedState), [storedState])
  const language = state.language
  const t = (value: string) => translateText(value, language)
  const [route, setRoute] = useState<Route>('dashboard')
  const [mobileOpen, setMobileOpen] = useState(false)
  const [compact, setCompact] = useState(false)
  const [collapsed, setCollapsed] = usePersistentState<Record<string, boolean>>('geoflow-nav-groups', {})
  const [createKind, setCreateKind] = useState<CreateKind>(null)
  const [taskModal, setTaskModal] = useState<{ mode: 'create' | 'duplicate' | 'inspect'; taskId: string | null; instance: string } | null>(null)
  const [instructionModal, setInstructionModal] = useState<{ mode: 'create' | 'inspect'; seed: WritingInstruction | null; instance: string } | null>(null)
  const [detail, setDetail] = useState<KeywordSet | Article | null>(null)
  const [knowledgeBaseId, setKnowledgeBaseId] = useState<string | null>(null)
  const [imageLibraryId, setImageLibraryId] = useState<string | null>(null)
  const [confirm, setConfirm] = useState<{ title: string; action: () => void } | null>(null)
  const [toast, setToast] = useState('')

  useEffect(() => { document.documentElement.dataset.theme = state.theme }, [state.theme])
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }
  const navigate = (next: Route) => { setRoute(next); setMobileOpen(false) }
  const openKnowledgeBase = (knowledgeBase: KnowledgeBase) => { setKnowledgeBaseId(knowledgeBase.id); setDetail(null); navigate('knowledge-base-detail') }
  const openImageLibrary = (imageLibrary: ImageLibrary) => { setImageLibraryId(imageLibrary.id); setDetail(null); navigate('image-library-detail') }
  const openCreationTask = (task?: CreationTask) => { setTaskModal({ instance: uid('task-modal'), mode: task ? 'duplicate' : 'create', taskId: task?.id || null }); setCreateKind(null) }
  const openInspectTask = (taskId: string) => setTaskModal({ instance: uid('task-modal'), mode: 'inspect', taskId })
  const openInstructionModal = (mode: 'create' | 'inspect', seed: WritingInstruction | null) => setInstructionModal({ instance: uid('instruction-modal'), mode, seed })
  const patch = (next: Partial<AppState>) => setStoredState(current => normalizeState({ ...normalizeState(current), ...next }))
  const toggleTheme = () => patch({ theme: state.theme === 'light' ? 'dark' : 'light' })
  useEffect(() => { document.documentElement.lang = language === 'zh' ? 'zh-CN' : 'en'; document.title = language === 'zh' ? 'GEO 运营' : 'GEO Operations' }, [language])
  const toggleLanguage = () => { const next = language === 'en' ? 'zh' : 'en'; patch({ language: next }) }
  const resetDemo = () => { setStoredState(normalizeState({ ...defaultAppState, language })); setKnowledgeBaseId(null); setRoute('dashboard'); notify(t('Demo data reset to the original local snapshot')) }

  const page = routeInfo[route]
  return <I18nProvider language={language} onLanguageChange={next => patch({ language: next })}><div className="app-shell">
    <Sidebar active={route} compact={compact} mobileOpen={mobileOpen} collapsed={collapsed} onCompact={() => setCompact(value => !value)} onToggleGroup={(group) => setCollapsed(value => ({ ...value, [group]: !value[group] }))} onNavigate={navigate} onClose={() => setMobileOpen(false)} balance={state.balance} />
    <div className="app-main">
      <header className="topbar">
        <button className="icon-button mobile-menu" aria-label={t("Open navigation")} onClick={() => setMobileOpen(true)}><Menu size={19} /></button>
        <div className="breadcrumbs"><span>{t('Workspace')}</span><ChevronRight size={14} /><strong>{t(page.label)}</strong></div>
        <div className="topbar-actions"><button className="connection" onClick={() => notify(t('Connection is simulated and local-only'))}><span className="status-dot" /> {t('Local only')} <span className="connection-version">{t("v0.8.4-demo")}</span></button><button className="language-toggle" aria-label={t('Language')} onClick={toggleLanguage}>{language === 'en' ? '简体中文' : 'English'}</button><button className="icon-button" aria-label={t('Toggle theme')} onClick={toggleTheme}>{state.theme === 'light' ? <Moon size={17} /> : <Sun size={17} />}</button><button className="balance-chip" onClick={() => navigate('compute-points')}><Zap size={14} /> {state.balance.toLocaleString()} <span>{t('points')}</span></button><button className="avatar" aria-label={t('Open user menu')} onClick={() => navigate('settings')}>{t("ET")}</button></div>
      </header>
      <main className="page-wrap">
        <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-mark" /> {t('CONTENT OPERATIONS · SIMULATED')}</div><h1>{t(page.label)}</h1><p className="lede">{t(page.description)}</p></div>{route === 'dashboard' && <button className="button button-primary" onClick={() => notify(t('Report simulation queued locally'))}><RefreshCw size={16} /> {t('Simulate report')}</button>}</div>
        <PageRouter route={route} state={state} patch={patch} navigate={navigate} notify={notify} onCreate={setCreateKind} onCreateTask={openCreationTask} onInspectTask={openInspectTask} onOpenInstruction={openInstructionModal} onDetail={setDetail} onOpenKnowledgeBase={openKnowledgeBase} onOpenImageLibrary={openImageLibrary} selectedKnowledgeBaseId={knowledgeBaseId} selectedImageLibraryId={imageLibraryId} onConfirm={setConfirm} />
      </main>
    </div>
    {taskModal ? <CreationTaskModal key={taskModal.instance} initialMode={taskModal.mode} seed={taskModal.taskId ? state.creationTasks.find(task => task.id === taskModal.taskId) || null : null} state={state} patch={patch} onClose={() => setTaskModal(null)} notify={notify} /> : createKind && <CreateModal kind={createKind} state={state} patch={patch} onClose={() => setCreateKind(null)} notify={notify} />}
    {instructionModal ? <InstructionModal key={instructionModal.instance} initialMode={instructionModal.mode} seed={instructionModal.seed} state={state} patch={patch} onClose={() => setInstructionModal(null)} notify={notify} /> : null}
    {detail && <InteractiveDetailDrawer item={detail} state={state} patch={patch} onClose={() => setDetail(null)} onConfirm={setConfirm} notify={notify} />}
    {confirm && <ConfirmModal title={confirm.title} onClose={() => setConfirm(null)} onConfirm={() => { confirm.action(); setConfirm(null) }} />}
    {toast && <div className="toast"><Sparkles size={15} />{toast}</div>}
  </div></I18nProvider>
}

function Sidebar({ active, compact, mobileOpen, collapsed, onCompact, onToggleGroup, onNavigate, onClose, balance }: { active: Route; compact: boolean; mobileOpen: boolean; collapsed: Record<string, boolean>; onCompact: () => void; onToggleGroup: (group: string) => void; onNavigate: (route: Route) => void; onClose: () => void; balance: number }) {
  const { t: tr } = useTranslation()
  return <><aside className={`sidebar ${compact ? 'sidebar-compact' : ''} ${mobileOpen ? 'sidebar-mobile-open' : ''}`}>
    <div className="brand-lockup"><div className="brand-mark">{tr("G")}</div><div className="brand-copy"><strong>{tr("Workspace")}</strong><span>{tr("GEO operations")}</span></div><button className="icon-button sidebar-close mobile-only" aria-label={tr("Close navigation")} onClick={onClose}><X size={17} /></button></div>
    <button className="workspace-switcher" onClick={() => onNavigate('settings')}><span className="workspace-avatar">{tr("G")}</span><span className="workspace-copy"><strong>{tr("Workspace")}</strong><small>{tr("example.local")}</small></span><ChevronDown size={15} /></button>
    <div className="sidebar-nav">{navGroups.map(group => <div className="nav-group" key={group.label}><button className="nav-group-heading" onClick={() => onToggleGroup(group.label)}><span>{tr(group.label)}</span>{!compact && (collapsed[group.label] ? <ChevronRight size={13} /> : <ChevronDown size={13} />)}</button>{!collapsed[group.label] && group.items.map(item => <button key={item.route} className={`nav-item ${active === item.route ? 'active' : ''}`} title={compact ? tr(item.label) : undefined} onClick={() => onNavigate(item.route)}><item.icon size={17} /><span>{tr(item.label)}</span>{item.badge && !compact && <em>{item.badge}</em>}</button>)}</div>)}</div>
    <div className="sidebar-spacer" /><div className="points-card"><div className="points-icon"><Zap size={14} /></div><div><strong>{balance.toLocaleString()}</strong><span>{tr("compute points")}</span></div><ArrowUpRight size={14} /></div><button className="collapse-button" onClick={onCompact}>{compact ? <PanelLeftOpen size={16} /> : <PanelLeftClose size={16} />}<span>{tr(compact ? 'Expand sidebar' : 'Collapse sidebar')}</span></button><div className="sidebar-footer"><span>{tr("LOCAL DEMO · v0.8.4")}</span><CircleHelp size={14} /></div>
  </aside>{mobileOpen && <button className="nav-scrim" aria-label={tr("Close navigation")} onClick={onClose} />}</>
}

function DashboardFallback() { const { t: tr } = useTranslation(); return <div className="content-stack"><section className="card"><div className="card-header"><div><h2>{tr("Loading dashboard…")}</h2><p>{tr("Recharts and the dashboard module are being loaded locally.")}</p></div></div><div className="kpi-grid"><div className="card kpi-card cobalt"><div className="kpi-top"><span>{tr("Keyword coverage")}</span></div><strong className="kpi-value">—</strong></div><div className="card kpi-card cyan"><div className="kpi-top"><span>{tr("Content output")}</span></div><strong className="kpi-value">—</strong></div><div className="card kpi-card green"><div className="kpi-top"><span>{tr("Brand mentions")}</span></div><strong className="kpi-value">—</strong></div><div className="card kpi-card violet"><div className="kpi-top"><span>{tr("Model calls")}</span></div><strong className="kpi-value">—</strong></div></div></section></div> }

function PageRouter({ route, state, patch, navigate, notify, onCreate, onCreateTask, onInspectTask, onOpenInstruction, onDetail, onOpenKnowledgeBase, onOpenImageLibrary, selectedKnowledgeBaseId, selectedImageLibraryId, onConfirm }: { route: Route; state: AppState; patch: (next: Partial<AppState>) => void; navigate: (route: Route) => void; notify: (message: string) => void; onCreate: (kind: CreateKind) => void; onCreateTask: (task?: CreationTask) => void; onInspectTask: (taskId: string) => void; onOpenInstruction: (mode: 'create' | 'inspect', seed: WritingInstruction | null) => void; onDetail: (item: KeywordSet | Article) => void; onOpenKnowledgeBase: (item: KnowledgeBase) => void; onOpenImageLibrary: (item: ImageLibrary) => void; selectedKnowledgeBaseId: string | null; selectedImageLibraryId: string | null; onConfirm: (confirmation: { title: string; action: () => void }) => void }) {
  if (route === 'dashboard') return <Suspense fallback={<DashboardFallback />}><Dashboard state={state} patch={patch} navigate={navigate} onOpenKnowledgeBase={onOpenKnowledgeBase} onDetail={onDetail} notify={notify} /></Suspense>
  if (route === 'knowledge-base-detail') { const knowledgeBase = state.knowledgeBases.find(item => item.id === selectedKnowledgeBaseId); return knowledgeBase ? <KnowledgeBaseDetailPage knowledgeBase={knowledgeBase} state={state} patch={patch} navigate={navigate} notify={notify} onBack={() => navigate('knowledge-bases')} onConfirm={onConfirm} /> : <InfoPage route="knowledge-bases" navigate={navigate} /> }
  if (route === 'image-library-detail') { const imageLibrary = state.imageLibraries.find(item => item.id === selectedImageLibraryId); return imageLibrary ? <ImageLibraryDetailPage imageLibrary={imageLibrary} state={state} patch={patch} navigate={navigate} notify={notify} onBack={() => navigate('image-libraries')} onConfirm={onConfirm} /> : <InfoPage route="image-libraries" navigate={navigate} /> }
  if (route === 'knowledge-bases' || route === 'image-libraries') return <AssetPage kind={route === 'knowledge-bases' ? 'knowledge' : 'image'} state={state} onCreate={onCreate} onConfirm={onConfirm} patch={patch} notify={notify} onSwitch={next => navigate(next)} onOpenKnowledgeBase={onOpenKnowledgeBase} onOpenImageLibrary={onOpenImageLibrary} />
  if (route === 'keyword-distillation') return <KeywordDistillationPage state={state} onCreate={() => onCreate('keyword')} onDetail={onDetail} />
  if (route === 'writing-instructions') return <InstructionsPage state={state} patch={patch} notify={notify} onCreate={() => onOpenInstruction('create', null)} onInspect={(item) => onOpenInstruction('inspect', item)} />
  if (route === 'automatic-creation') return <CreationPage state={state} onCreate={() => onCreateTask()} onCreateTask={onCreateTask} onInspectTask={onInspectTask} patch={patch} navigate={navigate} notify={notify} onConfirm={onConfirm} />
  if (route === 'article-list') return <ArticlePage state={state} onDetail={onDetail} />
  if (route === 'personal-media') return <PublishingPage state={state} patch={patch} onCreate={() => onCreate('publishing')} onConfirm={onConfirm} notify={notify} />
  if (route === 'model-validation') return <ValidationPage2 state={state} patch={patch} notify={notify} />
  if (route === 'compute-points') return <PointsPage state={state} patch={patch} notify={notify} />
  if (route === 'admin') return <AdminPage2 state={state} patch={patch} notify={notify} />
  if (route === 'settings') return <SettingsPage state={state} patch={patch} notify={notify} />
  if (['records', 'accounts', 'website-media', 'influencers', 'official-seo'].includes(route)) return <OperationsPage route={route} state={state} patch={patch} notify={notify} />
  return <InfoPage route={route} navigate={navigate} />
}

export function KnowledgeBaseDetailPage({ knowledgeBase, state, patch, navigate, notify, onBack, onConfirm }: { knowledgeBase: KnowledgeBase; state: AppState; patch: (next: Partial<AppState>) => void; navigate: (route: Route) => void; notify: (message: string) => void; onBack: () => void; onConfirm: (confirmation: { title: string; action: () => void }) => void }) {
  const { t: tr } = useTranslation()
  const [editingId, setEditingId] = useState<string | null>(null); const [editorOpen, setEditorOpen] = useState(false)
  const [draft, setDraft] = useState<{ category: KnowledgeEntry['category']; title: string; body: string; status: KnowledgeEntry['status'] }>({ category: 'Source', title: '', body: '', status: 'Review' })
  const flow = state.guidedWorkflow
  const approvedIds = knowledgeBase.entries.filter(entry => entry.status === 'Approved').map(entry => entry.id)
  const flowEntryIds = flow.selectedEntryIds?.filter(id => knowledgeBase.entries.some(entry => entry.id === id)) || []
  const selectedIds = flowEntryIds.length ? flowEntryIds : approvedIds
  const saveEntry = () => {
    if (!draft.title.trim() || !draft.body.trim()) return
    const entry: KnowledgeEntry = { id: editingId || uid('entry'), category: draft.category, title: draft.title.trim(), body: draft.body.trim(), status: draft.status, updated: 'just now' }
    patch({ knowledgeBases: state.knowledgeBases.map(item => item.id === knowledgeBase.id ? { ...item, entries: editingId ? item.entries.map(existing => existing.id === editingId ? entry : existing) : [entry, ...item.entries], sourceCount: editingId ? item.sourceCount : item.entries.length + 1, updated: 'just now' } : item) })
    setEditingId(null); setEditorOpen(false); setDraft({ category: 'Source', title: '', body: '', status: 'Review' }); notify(tr(editingId ? 'Knowledge entry edited locally' : 'Knowledge entry added locally'))
  }
  const startEdit = (entry: KnowledgeEntry) => { setEditingId(entry.id); setEditorOpen(true); setDraft({ category: entry.category, title: entry.title, body: entry.body, status: entry.status }) }
  const remove = (entry: KnowledgeEntry) => onConfirm({ title: `Delete ${entry.title}?`, action: () => { patch({ knowledgeBases: state.knowledgeBases.map(item => item.id === knowledgeBase.id ? { ...item, entries: item.entries.filter(existing => existing.id !== entry.id), sourceCount: Math.max(0, item.entries.length - 1), updated: 'just now' } : item) }); notify(tr('Knowledge entry deleted locally')) } })
  const toggleStatus = (entry: KnowledgeEntry) => { const status = entry.status === 'Approved' ? 'Review' : 'Approved'; patch({ knowledgeBases: state.knowledgeBases.map(item => item.id === knowledgeBase.id ? { ...item, entries: item.entries.map(existing => existing.id === entry.id ? { ...existing, status, updated: 'just now' } : existing) } : item) }); notify(tr(`Knowledge entry marked ${status.toLowerCase()}`)) }
  const toggleSelected = (entryId: string) => { const next = selectedIds.includes(entryId) ? selectedIds.filter(id => id !== entryId) : [...selectedIds, entryId]; patch({ guidedWorkflow: { ...flow, selectedEntryIds: next } }) }
  const useForGuidedFlow = () => { patch({ guidedWorkflow: { ...flow, selectedKnowledgeBaseId: knowledgeBase.id, selectedEntryIds: selectedIds, step: 2 } }); navigate('dashboard'); notify(tr('Knowledge entries selected for guided grounding')) }
  return <div className="kb-library-page"><div className="kb-library-toolbar"><button className="button button-outline" onClick={onBack}><ArrowLeft size={14} /> {tr('Back to knowledge bases')}</button><span className="simulated-label"><span className="status-dot" /> {tr('Local library')}</span></div><section className="kb-library-hero"><div><span className="eyebrow">{tr('KNOWLEDGE BASE · LOCAL LIBRARY')}</span><h2>{tr(knowledgeBase.name)}</h2><p>{tr(knowledgeBase.description)}</p></div><button className="button button-primary" onClick={() => { setEditingId(null); setEditorOpen(true); setDraft({ category: 'Source', title: '', body: '', status: 'Review' }) }}><Plus size={15} /> {tr('Add entry')}</button></section><section className="kb-library-meta"><span>{knowledgeBase.entries.length} {tr('entries')}</span><span>{knowledgeBase.entries.filter(entry => entry.status === 'Approved').length} {tr('approved')}</span><span>{tr(knowledgeBase.tone)} · {tr('Updated')} {tr(knowledgeBase.updated)}</span></section>{!editorOpen ? null : <section className="card kb-entry-editor"><div className="section-row"><div><h3>{tr(editingId ? 'Edit entry' : 'Add entry')}</h3><p>{tr('This entry is saved only in the current browser workspace.')}</p></div><button className="icon-button" aria-label={tr('Close editor')} onClick={() => { setEditingId(null); setEditorOpen(false); setDraft({ category: 'Source', title: '', body: '', status: 'Review' }) }}><X size={16} /></button></div><div className="kb-editor-grid"><label>{tr('Category')}<select value={draft.category} onChange={event => setDraft({ ...draft, category: event.target.value as KnowledgeEntry['category'] })}>{(['Source', 'Fact', 'Product', 'Research', 'Customer voice', 'Workflow'] as const).map(category => <option value={category} key={category}>{tr(category)}</option>)}</select></label><label>{tr('Entry status')}<select value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value as KnowledgeEntry['status'] })}><option value="Approved">{tr('Approved')}</option><option value="Review">{tr('Review')}</option><option value="Draft">{tr('Draft')}</option></select></label><label className="wide-field">{tr('Entry title')}<input autoFocus value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} placeholder={tr('Entry title')} /></label><label className="wide-field">{tr('Entry body')}<textarea rows={5} value={draft.body} onChange={event => setDraft({ ...draft, body: event.target.value })} placeholder={tr('Write the local fact, source note, or product detail here.')} /></label></div><div className="editor-actions"><button className="button button-outline" onClick={() => { setEditingId(null); setEditorOpen(false); setDraft({ category: 'Source', title: '', body: '', status: 'Review' }) }}>{tr('Cancel')}</button><button className="button button-primary" disabled={!draft.title.trim() || !draft.body.trim()} onClick={saveEntry}><Check size={14} /> {tr('Save entry')}</button></div></section>}{knowledgeBase.entries.length === 0 && <EmptyState title={tr('No entries yet')} text={tr('Add the first local knowledge entry to use it as grounding.')} />}<div className="kb-entry-grid">{knowledgeBase.entries.map(entry => <article className="card kb-entry-card" key={entry.id}><div className="kb-entry-card-head"><span className="kb-category-chip">{tr(entry.category)}</span><span className={`status-pill ${entry.status === 'Approved' ? 'active' : entry.status === 'Review' ? 'review' : 'draft'}`}>{tr(entry.status)}</span></div><h3>{tr(entry.title)}</h3><p>{tr(entry.body)}</p><div className="kb-entry-card-foot"><span>{tr('Updated')} {tr(entry.updated)}</span><label className="entry-select"><input type="checkbox" checked={selectedIds.includes(entry.id)} onChange={() => toggleSelected(entry.id)} /> {tr('Use for grounding')}</label><div className="row-actions"><button className="text-button" onClick={() => startEdit(entry)}><PenLine size={12} /> {tr('Edit')}</button><button className="text-button" onClick={() => toggleStatus(entry)}><Check size={12} /> {tr(entry.status === 'Approved' ? 'Send to review' : 'Approve')}</button><button className="text-button danger-text" onClick={() => remove(entry)}><Trash2 size={12} /> {tr('Delete')}</button></div></div></article>)}</div><section className="card kb-grounding-panel"><div><span className="eyebrow">{tr('GUIDED GROUNDING')}</span><h3>{tr('Use selected entries in the guided workflow')}</h3><p>{tr('The next generated article will retain these entry IDs as its local grounding context.')}</p></div><button className="button button-primary" disabled={!selectedIds.length} onClick={useForGuidedFlow}><ArrowUpRight size={14} /> {tr('Continue')}</button></section></div>
}

export function AssetPage({ kind, state, patch, onCreate, onConfirm, notify, onSwitch, onOpenKnowledgeBase, onOpenImageLibrary }: { kind: 'knowledge' | 'image'; state: AppState; patch: (next: Partial<AppState>) => void; onCreate: (kind: CreateKind) => void; onConfirm: (confirmation: { title: string; action: () => void }) => void; notify: (message: string) => void; onSwitch: (route: Route) => void; onOpenKnowledgeBase: (item: KnowledgeBase) => void; onOpenImageLibrary: (item: ImageLibrary) => void }) {
  const { t: tr } = useTranslation()
  const [search, setSearch] = useState('')
  const isKnowledge = kind === 'knowledge'; const items = isKnowledge ? state.knowledgeBases : state.imageLibraries
  const filtered = items.filter(item => item.name.toLowerCase().includes(search.toLowerCase()) || item.description.toLowerCase().includes(search.toLowerCase()))
  const remove = (id: string, name: string) => onConfirm({ title: `Delete ${name}?`, action: () => { patch(isKnowledge ? { knowledgeBases: state.knowledgeBases.filter(item => item.id !== id) } : { imageLibraries: state.imageLibraries.filter(item => item.id !== id) }); notify(tr(`${name} deleted locally`)) } })
  return <div className="content-stack"><section className="subnav-tabs"><button className={isKnowledge ? 'active' : ''} onClick={() => onSwitch('knowledge-bases')}>{tr("Knowledge Bases")} <b>{state.knowledgeBases.length}</b></button><button className={!isKnowledge ? 'active' : ''} onClick={() => onSwitch('image-libraries')}>{tr("Image Libraries")} <b>{state.imageLibraries.length}</b></button></section>{isKnowledge ? <div className="local-disclosure"><Info size={15} /><span><strong>{tr("Guided local demo")}</strong>{tr("Open a knowledge base to review seeded entries, then run the question-to-validation flow.")}</span></div> : <div className="local-disclosure"><Info size={15} /><span><strong>{tr("Local image album")}</strong>{tr("Each image stays in this browser as either a sample placeholder or an uploaded base64 data URL. Nothing is sent or stored remotely.")}</span></div>}<Toolbar search={search} setSearch={setSearch} action={<button className="button button-primary" onClick={() => onCreate(kind)}><Plus size={15} /> {tr(isKnowledge ? 'Create knowledge base' : 'Create image library')}</button>} /><div className="asset-grid">{filtered.map(item => <AssetCard key={item.id} item={item} kind={kind} onDelete={() => remove(item.id, item.name)} onOpen={isKnowledge ? () => onOpenKnowledgeBase(item as KnowledgeBase) : () => onOpenImageLibrary(item as ImageLibrary)} />)}</div>{filtered.length === 0 && <EmptyState title={tr("No local assets found")} text={tr("Try a different search or create the first asset.")} />}</div>
}

function AssetCard({ item, kind, onDelete, onOpen }: { item: KnowledgeBase | ImageLibrary; kind: 'knowledge' | 'image'; onDelete: () => void; onOpen?: () => void }) { const { t: tr } = useTranslation(); const count = kind === 'knowledge' ? (item as KnowledgeBase).entries.length : (item as ImageLibrary).imageCount; const meta = kind === 'knowledge' ? `${tr((item as KnowledgeBase).tone)} ${tr("tone")}` : `${tr((item as ImageLibrary).style)} ${tr("style")}`; const open = () => onOpen?.(); return <article className={`asset-card card ${onOpen ? 'asset-card-interactive' : ''}`} onClick={open} onKeyDown={event => { if (onOpen && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); open() } }} role={onOpen ? 'button' : undefined} tabIndex={onOpen ? 0 : undefined}><div className={`asset-cover ${kind}`}><span>{kind === 'knowledge' ? <Database size={20} /> : <Image size={20} />}</span><button className="icon-button light-icon" aria-label={tr(`More actions for ${item.name}`)} onClick={event => { event.stopPropagation(); onDelete() }}><Trash2 size={15} /></button></div><div className="asset-body"><div className="asset-title"><h3>{tr(item.name)}</h3><span className="status-pill active">{tr("Active")}</span></div><p>{tr(item.description)}</p><div className="asset-meta"><strong>{count}</strong><span>{tr(kind === 'knowledge' ? 'entries' : 'images')}</span><i />{meta}<span className="asset-date">{tr("Updated")} {tr(item.updated)}</span></div>{onOpen && <button className="text-button asset-open" onClick={event => { event.stopPropagation(); open() }}>{tr("Open details")} <ChevronRight size={13} /></button>}</div></article> }

function formatBytes(size: number) {
  if (size < 1024) return `${size} B`
  if (size < 1024 * 1024) return `${Math.round(size / 1024)} KB`
  return `${(size / (1024 * 1024)).toFixed(1)} MB`
}

export function ImageLibraryDetailPage({ imageLibrary, state, patch, navigate, notify, onBack, onConfirm }: { imageLibrary: ImageLibrary; state: AppState; patch: (next: Partial<AppState>) => void; navigate: (route: Route) => void; notify: (message: string) => void; onBack: () => void; onConfirm: (confirmation: { title: string; action: () => void }) => void }) {
  const { t: tr } = useTranslation()
  const [page, setPage] = useState(1)
  const [addOpen, setAddOpen] = useState(false)
  const [draft, setDraft] = useState({ name: '', size: '240' })
  const [uploading, setUploading] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const MAX_IMAGE_BYTES = 1024 * 1024
  const selectedIds = imageLibrary.selectedImageIds || []
  const pageSize = 6
  const totalPages = Math.max(1, Math.ceil(imageLibrary.images.length / pageSize))
  const shown = imageLibrary.images.slice((page - 1) * pageSize, page * pageSize)
  const toggleSelected = (imageId: string) => {
    const next = selectedIds.includes(imageId) ? selectedIds.filter(id => id !== imageId) : [...selectedIds, imageId]
    patch({ imageLibraries: state.imageLibraries.map(item => item.id === imageLibrary.id ? { ...item, selectedImageIds: next } : item) })
  }
  const selectPage = (checked: boolean) => {
    const pageIds = shown.map(image => image.id)
    const next = checked ? [...new Set([...selectedIds, ...pageIds])] : selectedIds.filter(id => !pageIds.includes(id))
    patch({ imageLibraries: state.imageLibraries.map(item => item.id === imageLibrary.id ? { ...item, selectedImageIds: next } : item) })
  }
  const addImage = (event: FormEvent) => {
    event.preventDefault()
    const name = draft.name.trim() || `local-sample-${imageLibrary.images.length + 1}.png`
    const sizeKb = Math.max(1, Number(draft.size) || 240)
    const created: LocalImage = { id: uid('image'), name, size: sizeKb * 1024, width: 1600, height: 1000, kind: 'sample', updated: 'just now' }
    patch({ imageLibraries: state.imageLibraries.map(item => item.id === imageLibrary.id ? { ...item, images: [created, ...item.images], imageCount: item.images.length + 1, updated: 'just now' } : item) })
    setPage(1); setDraft({ name: '', size: '240' }); setAddOpen(false); notify(tr('Local sample image added'))
  }
  const readFileAsDataUrl = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file) })
  const readImageDimensions = (dataUrl: string) => new Promise<{ width: number; height: number }>((resolve) => { const probe = new window.Image(); probe.onload = () => resolve({ width: probe.naturalWidth, height: probe.naturalHeight }); probe.onerror = () => resolve({ width: 0, height: 0 }); probe.src = dataUrl })
  const uploadFiles = async (files: FileList | null) => {
    if (!files || !files.length) return
    setUploading(true)
    const skipped: string[] = []
    const accepted: LocalImage[] = []
    for (const file of Array.from(files)) {
      if (!file.type.startsWith('image/')) { skipped.push(`${file.name} (not an image)`); continue }
      if (file.size > MAX_IMAGE_BYTES) { skipped.push(`${file.name} (over 1 MB)`); continue }
      try {
        const dataUrl = await readFileAsDataUrl(file)
        const { width, height } = await readImageDimensions(dataUrl)
        accepted.push({ id: uid('image'), name: file.name, size: file.size, width, height, kind: 'uploaded', updated: 'just now', dataUrl })
      } catch (error) { skipped.push(`${file.name} (read failed)`) }
    }
    if (accepted.length) {
      patch({ imageLibraries: state.imageLibraries.map(item => item.id === imageLibrary.id ? { ...item, images: [...accepted, ...item.images], imageCount: item.images.length + accepted.length, updated: 'just now' } : item) })
      setPage(1)
      notify(tr(`${accepted.length} image${accepted.length === 1 ? '' : 's'} stored locally from your device`))
    }
    if (skipped.length) notify(tr(`Skipped: ${skipped.join(', ')}`))
    setUploading(false)
    if (fileInputRef.current) fileInputRef.current.value = ''
  }
  const removeImage = (image: LocalImage) => onConfirm({ title: `Delete ${image.name}?`, action: () => { patch({ imageLibraries: state.imageLibraries.map(item => item.id === imageLibrary.id ? { ...item, images: item.images.filter(existing => existing.id !== image.id), selectedImageIds: (item.selectedImageIds || []).filter(id => id !== image.id), imageCount: Math.max(0, item.images.length - 1), updated: 'just now' } : item) }); notify(tr('Image deleted locally')) } })
  const allPageSelected = shown.length > 0 && shown.every(image => selectedIds.includes(image.id))
  return <div className="kb-library-page image-library-detail-page"><div className="kb-library-toolbar"><button className="button button-outline" onClick={onBack}><ArrowLeft size={14} /> {tr('Back to image libraries')}</button><span className="simulated-label"><span className="status-dot" /> {tr('Local album')}</span></div><section className="kb-library-hero"><div><span className="eyebrow">{tr('IMAGE LIBRARY · LOCAL ALBUM')}</span><h2>{tr(imageLibrary.name)}</h2><p>{tr(imageLibrary.description)}</p></div><button className="button button-primary" onClick={() => setAddOpen(value => !value)}><Plus size={15} /> {tr('Add image')}</button></section><section className="kb-library-meta"><span>{imageLibrary.images.length} {tr('images')}</span><span>{selectedIds.length} {tr('selected')}</span><span>{tr(imageLibrary.style)} · {tr('Updated')} {tr(imageLibrary.updated)}</span></section><div className="local-disclosure"><Info size={15} /><span><strong>{tr('Browser-local only')}</strong>{tr('Sample placeholders are metadata; uploaded images are stored as base64 data URLs inside this browser. Nothing is sent, uploaded, or persisted remotely.')}</span></div>{addOpen && <section className="card image-add-panel"><div className="section-row"><div><h3>{tr('Add local image')}</h3><p>{tr('Upload a real file from your device or add a sample placeholder. Both stay in this localStorage snapshot.')}</p></div><button className="icon-button" aria-label={tr('Close editor')} onClick={() => setAddOpen(false)}><X size={16} /></button></div><div className="image-upload-zone"><span className="image-upload-icon"><Upload size={20} /></span><div className="image-upload-text"><strong>{tr('Upload from device')}</strong><span>{tr('PNG, JPEG, or WebP up to 1 MB. The file is read here and stored as a base64 data URL inside browser localStorage.')}</span></div><input ref={fileInputRef} type="file" accept="image/*" multiple onChange={event => uploadFiles(event.target.files)} className="image-upload-input" aria-label={tr('Upload images from device')} /><button type="button" className="button button-primary" onClick={() => fileInputRef.current?.click()} disabled={uploading}><Upload size={14} /> {uploading ? tr('Reading files…') : tr('Choose files')}</button></div><div className="image-add-divider"><span>{tr('or')}</span></div><form className="image-add-form" onSubmit={addImage}><label>{tr('Filename')}<input autoFocus value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} placeholder={tr('e.g. workflow-note.png')} /></label><label>{tr('Approximate size')}<div className="input-with-suffix"><input type="number" min="1" value={draft.size} onChange={event => setDraft({ ...draft, size: event.target.value })} /><span>KB</span></div></label><div className="editor-actions"><button type="button" className="button button-outline" onClick={() => setAddOpen(false)}>{tr('Cancel')}</button><button type="submit" className="button button-primary"><Plus size={14} /> {tr('Add sample placeholder')}</button></div></form></section>}<section className="image-selection-bar"><label><input type="checkbox" checked={allPageSelected} onChange={event => selectPage(event.target.checked)} /> {tr('Select visible')}</label><span>{selectedIds.length ? `${selectedIds.length} ${tr('images selected for task setup')}` : tr('No images selected')}</span><button className="text-button" onClick={() => navigate('automatic-creation')} disabled={!selectedIds.length}>{tr('Use in automatic creation')} <ArrowUpRight size={13} /></button></section>{imageLibrary.images.length === 0 ? <EmptyState title={tr('This album is empty')} text={tr('Add a local sample placeholder to make it available to task setup.')} /> : <><div className="image-album-grid">{shown.map((image, index) => <article className={`card image-album-card ${selectedIds.includes(image.id) ? 'selected' : ''}`} key={image.id}><div className={`image-thumb image-thumb-${(index + page) % 5}`}>{image.dataUrl ? <img src={image.dataUrl} alt={image.name} className="image-thumb-img" /> : <Image size={28} />}<span>{tr(image.kind === 'sample' ? 'Sample placeholder' : image.kind === 'uploaded' ? 'Uploaded from device' : 'Local metadata')}</span></div><div className="image-album-body"><div className="image-card-title"><label><input type="checkbox" checked={selectedIds.includes(image.id)} onChange={() => toggleSelected(image.id)} /><strong>{tr(image.name)}</strong></label><button className="icon-button" aria-label={tr(`Delete ${image.name}`)} onClick={() => removeImage(image)}><Trash2 size={14} /></button></div><p>{formatBytes(image.size)} · {image.width} × {image.height}px</p><small>{tr('Updated')} {tr(image.updated)}</small></div></article>)}</div><div className="table-footer album-pagination"><span>{tr(`Page ${page}`)} · {imageLibrary.images.length} {tr('total images')}</span><div className="pagination"><button className="icon-button" disabled={page === 1} aria-label={tr('Previous page')} onClick={() => setPage(value => Math.max(1, value - 1))}>‹</button><span>{page} / {totalPages}</span><button className="icon-button" disabled={page === totalPages} aria-label={tr('Next page')} onClick={() => setPage(value => Math.min(totalPages, value + 1))}>›</button></div></div></>}</div>
}


export function InstructionsPage({ state, patch, notify, onCreate, onInspect }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void; onCreate: () => void; onInspect: (item: WritingInstruction) => void }) {
  const { t: tr } = useTranslation()
  const [group, setGroup] = useState<'All' | WritingInstruction['group']>('All')
  const [search, setSearch] = useState('')
  const filtered = state.instructions.filter(item => (group === 'All' || item.group === group) && `${item.title} ${item.description}`.toLowerCase().includes(search.toLowerCase()))
  return <div className="content-stack"><div className="segmented"><button className={group === 'All' ? 'active' : ''} onClick={() => setGroup('All')}>{tr("All")} <b>{state.instructions.length}</b></button>{(['Article', 'Title', 'Traffic Replication'] as const).map(name => <button key={name} className={group === name ? 'active' : ''} onClick={() => setGroup(name)}>{tr(name)}</button>)}<span className="segmented-spacer" /><button className="button button-primary" onClick={onCreate}><Plus size={15} /> {tr("New instruction")}</button></div><Toolbar search={search} setSearch={setSearch} /><div className="instruction-groups">{(['Article', 'Title', 'Traffic Replication'] as const).map(name => { const items = filtered.filter(item => item.group === name); return <section key={name}><div className="section-row"><div><h2>{tr(name)}</h2><p>{tr(name === 'Article' ? 'Body structure and editorial behavior.' : name === 'Title' ? 'Headlines that set the right promise.' : 'Competitive and search-language guidance.')}</p></div><span className="count-label">{items.length} {tr("instructions")}</span></div><div className="instruction-list">{items.map(item => <article className="card instruction-card instruction-card-clickable" key={item.id} onClick={() => onInspect(item)} role="button" tabIndex={0} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onInspect(item) } }}><span className={`instruction-icon ${name.toLowerCase().replace(' ', '-')}`}><PenLine size={16} /></span><div className="instruction-content"><div className="asset-title"><h3>{tr(item.title)}</h3><span className={`status-pill ${item.status.toLowerCase()}`}>{tr(item.status)}</span></div><p>{tr(item.description)}</p><small>{tr("Updated")} {tr(item.updated)}</small></div></article>)}</div></section> })}</div></div>
}

function CreationPageLegacy({ state, patch, onCreate, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; onCreate: () => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [search, setSearch] = useState(''); const tasks = state.creationTasks.filter(item => `${item.name} ${item.keyword} ${tr(item.status)}`.toLowerCase().includes(search.toLowerCase())); const toggle = (task: CreationTask) => { const status = task.status === 'Paused' ? 'Running' : 'Paused'; patch({ creationTasks: state.creationTasks.map(item => item.id === task.id ? { ...item, status } : item) }); notify(tr(`${task.name} is now ${status.toLowerCase()}`)) }; const duplicate = (task: CreationTask) => { patch({ creationTasks: [...state.creationTasks, { ...task, id: uid('ct'), name: `${task.name} copy`, status: 'Ready', generated: 0, updated: 'just now' }] }); notify(tr('Creation task duplicated locally')) }; return <div className="content-stack"><section className="section-row"><div><h2>{tr("Automatic Creation")}</h2><p>{tr("Each task is explicit about the question set and instruction inputs it will use.")}</p></div><button className="button button-primary" onClick={onCreate}><Plus size={15} /> {tr("Create task")}</button></section><Toolbar search={search} setSearch={setSearch} /><div className="task-grid">{tasks.map(task => <article className="card task-card" key={task.id}><div className="task-head"><div><span className="eyebrow">{tr('TASK')} · {tr(task.status).toUpperCase()}</span><h3>{tr(task.name)}</h3></div><button className="icon-button" aria-label={tr(`Duplicate ${task.name}`)} onClick={() => duplicate(task)}><MoreHorizontal size={16} /></button></div><p className="task-keyword"><Tag size={14} /> {tr(task.keyword)} <span>· {task.questionCount} {tr("questions")}</span></p><div className="task-inputs"><span><PenLine size={13} />{tr(task.writingInstruction)}</span><span><FileText size={13} />{tr(task.titleInstruction)}</span><span><Database size={13} />{tr(task.knowledgeBase)}</span><span><Image size={13} />{tr(task.imageLibrary)}</span></div><div className="task-progress"><div><span>{tr("Generated")}</span><strong>{task.generated} / {task.target}</strong></div><div className="progress"><span style={{ width: `${Math.min(100, task.generated / task.target * 100)}%` }} /></div></div><div className="task-foot"><small>{tr("Updated")} {tr(task.updated)}</small><div><span className={`status-pill ${task.status.toLowerCase()}`}>{tr(task.status)}</span><button className="button button-small button-outline" onClick={() => toggle(task)}>{tr(task.status === 'Paused' ? 'Resume' : 'Pause')}</button></div></div></article>)}</div></div> }

export function CreationPage({ state, patch, onCreate, onCreateTask, onInspectTask, navigate, notify, onConfirm }: { state: AppState; patch: (next: Partial<AppState>) => void; onCreate: () => void; onCreateTask: (task?: CreationTask) => void; onInspectTask: (taskId: string) => void; navigate: (route: Route) => void; notify: (message: string) => void; onConfirm: (confirmation: { title: string; action: () => void }) => void }) {
  const { t: tr } = useTranslation()
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState('All statuses')
  const [expanded, setExpanded] = useState<Record<string, boolean>>({})
  const [refresh, setRefresh] = useState(0)
  const [runningTaskId, setRunningTaskId] = useState<string | null>(null)
  const tasks = state.creationTasks.filter(task => (status === 'All statuses' || task.status === status) && `${task.name} ${task.keyword} ${task.model || 'Local simulation'} ${task.knowledgeBase} ${tr(task.status)}`.toLowerCase().includes(search.toLowerCase()))
  const updateTask = (taskId: string, update: Partial<CreationTask>, message: string) => { patch({ creationTasks: state.creationTasks.map(task => task.id === taskId ? { ...task, ...update, updated: 'just now' } : task) }); notify(tr(message)) }
  const togglePause = (task: CreationTask) => {
    if (task.status === 'Completed') return
    const next = task.status === 'Running' ? 'Paused' : 'Running'
    const log: CreationLog = { id: uid('log'), time: 'just now', message: next === 'Paused' ? 'Simulated batch paused by the local operator.' : 'Simulated task resumed locally.', tone: 'info' }
    updateTask(task.id, { status: next, logs: [...(task.logs || []), log] }, next === 'Paused' ? 'Task paused locally' : 'Task resumed locally')
  }
  const runBatch = async (task: CreationTask) => {
    if (runningTaskId) return
    if (task.status === 'Completed' || task.generated >= task.target) { notify(tr('This task has reached its target')); return }
    const keywordSet = state.keywordSets.find(item => item.id === task.keywordSetId) || state.keywordSets.find(item => item.name === task.keyword)
    const knowledgeBase = state.knowledgeBases.find(item => item.id === task.knowledgeBaseIds?.[0])
    const imageLibrary = state.imageLibraries.find(item => item.id === task.imageLibraryId) || state.imageLibraries.find(item => item.name === task.imageLibrary)
    const availableImages = task.imageIds?.length ? task.imageIds : imageLibrary?.selectedImageIds?.length ? imageLibrary.selectedImageIds : (imageLibrary?.images || []).map(image => image.id)
    const remaining = Math.max(0, task.target - task.generated)
    const batchSize = Math.min(5, remaining)
    const useAgent = isRealModel(task.model)
    const writingInstruction = state.instructions.find(item => item.id === task.writingInstructionId)
    const titleInstruction = state.instructions.find(item => item.id === task.titleInstructionId)
    const groundingEntries = (task.groundingEntryIds || []).map(id => knowledgeBase?.entries.find(entry => entry.id === id)).filter(Boolean) as KnowledgeEntry[]

    if (!useAgent) {
      const generatedArticles: Article[] = Array.from({ length: batchSize }, (_, index) => {
        const prompt = keywordSet?.prompts[(task.generated + index) % Math.max(1, keywordSet.prompts.length)] || `${task.keyword} question ${task.generated + index + 1}`
        return { id: uid('article'), title: `${prompt.replace(/[?]+$/, '')} — local review draft`, keyword: task.keyword, task: task.name, model: task.model || 'Local simulation', status: 'Review', date: formatDate(), wordCount: 640, channel: 'Local review queue', knowledgeBaseId: knowledgeBase?.id || task.knowledgeBaseIds?.[0], prompt, groundedSourceIds: task.groundingEntryIds || [], creationTaskId: task.id, imageIds: availableImages.slice(0, task.imagesPerArticle || 0) }
      })
      const nextGenerated = task.generated + batchSize
      const log: CreationLog = { id: uid('log'), time: 'just now', message: `Created ${batchSize} review article record${batchSize === 1 ? '' : 's'} locally; no model call or network request was made.`, tone: 'success' }
      const nextStatus: CreationTask['status'] = nextGenerated >= task.target ? 'Completed' : 'Paused'
      const record: OperationsRecord = { id: uid('record'), type: 'Generation', summary: `${batchSize} local review article${batchSize === 1 ? '' : 's'} · ${task.name}`, owner: 'Editorial team', status: 'Complete', date: 'just now' }
      const ledger = { id: uid('ledger'), type: 'Usage' as const, detail: `Local simulation · ${task.name} · ${batchSize} articles`, amount: 0, balance: state.balance, date: 'just now' }
      patch({ articles: [...generatedArticles, ...state.articles], creationTasks: state.creationTasks.map(item => item.id === task.id ? { ...item, generated: nextGenerated, status: nextStatus, updated: 'just now', logs: [...(item.logs || []), log] } : item), records: [record, ...state.records], ledger: [ledger, ...state.ledger] })
      notify(tr(`${batchSize} review article records created locally`))
      return
    }

    setRunningTaskId(task.id)
    const startingLogs = [...(task.logs || []), { id: uid('log'), time: 'just now', message: `Live agent request sent via ${task.model} for one article.`, tone: 'info' as const }]
    patch({ creationTasks: state.creationTasks.map(item => item.id === task.id ? { ...item, status: 'Running' as const, updated: 'just now', logs: startingLogs } : item) })
    try {
      const result = await runAgentForTask(task, { keywordSet, knowledgeBase, groundingEntries, writingInstruction, titleInstruction })
      const article: Article = { ...result.article, id: uid('article'), imageIds: availableImages.slice(0, task.imagesPerArticle || 0) }
      const nextGenerated = task.generated + 1
      const log: CreationLog = { id: uid('log'), time: 'just now', message: result.logMessage, tone: result.logTone }
      const nextStatus: CreationTask['status'] = nextGenerated >= task.target ? 'Completed' : 'Paused'
      const record: OperationsRecord = { id: uid('record'), type: 'Generation', summary: `1 live article · ${task.name} via ${task.model}`, owner: 'Editorial team', status: 'Complete', date: 'just now' }
      patch({ articles: [article, ...state.articles], creationTasks: state.creationTasks.map(item => item.id === task.id ? { ...item, generated: nextGenerated, status: nextStatus, updated: 'just now', logs: [...(item.logs || []), log] } : item), records: [record, ...state.records] })
      notify(tr(result.logTone === 'warning' ? `Live agent returned a non-JSON draft — stored for review` : `Live agent produced a reviewable draft via ${task.model}`))
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Live agent request failed'
      const log: CreationLog = { id: uid('log'), time: 'just now', message: `Live agent request failed: ${message}`, tone: 'warning' }
      patch({ creationTasks: state.creationTasks.map(item => item.id === task.id ? { ...item, updated: 'just now', logs: [...(item.logs || []), log] } : item) })
      notify(tr(`Live agent failed — ${message}`))
    } finally {
      setRunningTaskId(null)
    }
  }
  const duplicate = (task: CreationTask) => onCreateTask(task)
  const remove = (task: CreationTask) => onConfirm({ title: `Delete ${task.name}?`, action: () => { patch({ creationTasks: state.creationTasks.filter(item => item.id !== task.id) }); notify(tr('Creation task deleted locally')) } })
  return <div className="content-stack"><section className="section-row"><div><span className="eyebrow">{tr('TASK WORKSPACE · LOCAL STATE')}</span><h2>{tr('Automatic Creation')}</h2><p>{tr('Reusable instructions, question pools, knowledge entries, and image selections are saved as a reviewable task configuration.')}</p></div><button className="button button-primary" onClick={onCreate}><Plus size={15} /> {tr('Create task')}</button></section><div className="local-disclosure"><Info size={15} /><span><strong>{tr('Dual execution mode')}</strong>{tr('Tasks using a simulated model create local Review article records only. Tasks using a real model (MiniMax) call the local proxy, which forwards to the upstream API; the proxy never exposes the key to the browser.')}</span></div><Toolbar search={search} setSearch={setSearch} selects={<select aria-label={tr('Filter creation tasks')} value={status} onChange={event => setStatus(event.target.value)}><option value="All statuses">{tr('All statuses')}</option><option value="Ready">{tr('Ready')}</option><option value="Running">{tr('Running')}</option><option value="Paused">{tr('Paused')}</option><option value="Completed">{tr('Completed')}</option></select>} action={<button className="button button-outline" onClick={() => { setRefresh(value => value + 1); notify(tr('Task list refreshed locally')) }}><RefreshCw size={14} /> {tr('Refresh')} <span className="refresh-count">{refresh > 0 ? refresh : ''}</span></button>} />{tasks.length === 0 ? <EmptyState title={tr('No creation tasks found')} text={tr('Create a task or adjust the local search and status filter.')} /> : <div className="task-grid">{tasks.map(task => { const percent = task.target ? Math.min(100, task.generated / task.target * 100) : 0; const isExpanded = Boolean(expanded[task.id]); return <article className="card task-card task-card-detailed task-card-clickable" key={task.id} onClick={() => onInspectTask(task.id)} role="button" tabIndex={0} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onInspectTask(task.id) } }}><div className="task-head"><div><span className="eyebrow">{tr('TASK')} · {tr(task.status).toUpperCase()}</span><h3>{tr(task.name)}</h3><small>{tr('Created')} {tr(task.created || task.updated)} · {tr('Updated')} {tr(task.updated)}</small></div><div className="task-card-actions" onClick={(event) => event.stopPropagation()}><span className={`status-pill ${task.status.toLowerCase()}`}>{tr(task.status)}</span><button className="icon-button" aria-label={tr(`Duplicate ${task.name}`)} onClick={(event) => { event.stopPropagation(); duplicate(task) }}><ClipboardList size={14} /></button><button className="icon-button danger-icon" aria-label={tr(`Delete ${task.name}`)} onClick={(event) => { event.stopPropagation(); remove(task) }}><Trash2 size={14} /></button></div></div><p className="task-keyword"><Tag size={14} /> {tr(task.keyword)} <span>· {task.questionCount} {tr('questions')}</span></p><div className="task-inputs task-inputs-detailed"><span><PenLine size={13} /><b>{tr('Body')}</b>{tr(task.writingInstruction)}</span><span><FileText size={13} /><b>{tr('Title')}</b>{tr(task.titleInstruction)}</span><span><Database size={13} /><b>{tr('Knowledge Bases')}</b>{tr(task.knowledgeBases?.join(', ') || task.knowledgeBase)}</span><span><Image size={13} /><b>{tr('Image Library')}</b>{tr(task.imageLibrary)} · {task.imageCount || 0} {tr('images')} · {task.imagesPerArticle || 0} {tr('per article')}</span></div><div className="task-config-meta"><span><Bot size={13} /> {tr('Model')} · {tr(task.model || 'Local simulation')}</span><span><ShieldCheck size={13} /> {tr('Local-only options')}</span><span>{task.groundingEntryIds?.length || 0} {tr('grounding entries')}</span></div><div className="task-progress"><div><span>{tr('Progress')}</span><strong>{task.generated} / {task.target} {tr('articles')}</strong></div><div className="progress"><span style={{ width: `${percent}%` }} /></div></div><div className="task-actions-row"><button className="button button-small button-primary" disabled={task.status === 'Completed' || runningTaskId === task.id} onClick={() => runBatch(task)}><WandSparkles size={13} className={runningTaskId === task.id ? 'spin' : ''} /> {tr(runningTaskId === task.id ? (isRealModel(task.model) ? 'Calling live agent…' : 'Running batch…') : (isRealModel(task.model) ? 'Call live agent' : 'Run next batch'))}</button>{task.status !== 'Completed' && <button className="button button-small button-outline" onClick={() => togglePause(task)}>{task.status === 'Running' ? tr('Pause') : tr('Resume')}</button>}<button className="text-button" onClick={() => navigate('article-list')}><FileText size={13} /> {tr('Article List')}</button><button className="text-button" onClick={() => setExpanded(current => ({ ...current, [task.id]: !current[task.id] }))}>{isExpanded ? <ChevronDown size={13} /> : <ChevronRight size={13} />} {tr(isExpanded ? 'Hide execution log' : 'Show execution log')}</button></div>{isExpanded && <div className="execution-log"><div className="execution-log-head"><strong>{tr('Sanitized execution log')}</strong><span>{tr('Local events only')}</span></div>{(task.logs || []).slice().reverse().map(log => <div className="execution-log-row" key={log.id}><span className={`log-dot ${log.tone}`} /><small>{tr(log.time)}</small><p>{tr(log.message)}</p></div>)}</div>}</article>})}</div>}</div>
}

export function CreationTaskModal({ initialMode, seed, state, patch, onClose, notify }: { initialMode: 'create' | 'duplicate' | 'inspect'; seed: CreationTask | null; state: AppState; patch: (next: Partial<AppState>) => void; onClose: () => void; notify: (message: string) => void }) {
  const { t: tr } = useTranslation()
  const [mode, setMode] = useState<'create' | 'edit' | 'duplicate' | 'inspect'>(initialMode)
  const findKeyword = () => seed?.keywordSetId || state.keywordSets.find(item => item.name === seed?.keyword)?.id || state.keywordSets[0]?.id || ''
  const findBody = () => seed?.writingInstructionId || state.instructions.find(item => item.title === seed?.writingInstruction && item.group === 'Article')?.id || state.instructions.find(item => item.group === 'Article')?.id || ''
  const findTitle = () => seed?.titleInstructionId || state.instructions.find(item => item.title === seed?.titleInstruction && item.group === 'Title')?.id || state.instructions.find(item => item.group === 'Title')?.id || ''
  const findKnowledge = () => seed?.knowledgeBaseIds?.length ? seed.knowledgeBaseIds : seed ? state.knowledgeBases.filter(item => (seed.knowledgeBases || [seed.knowledgeBase]).includes(item.name)).map(item => item.id).slice(0, 1) : (state.knowledgeBases[0] ? [state.knowledgeBases[0].id] : [])
  const [name, setName] = useState(seed ? `${seed.name}${initialMode === 'duplicate' ? ' copy' : ''}` : '')
  const [keywordSetId, setKeywordSetId] = useState(findKeyword())
  const [bodyInstructionId, setBodyInstructionId] = useState(findBody())
  const [titleInstructionId, setTitleInstructionId] = useState(findTitle())
  const [knowledgeBaseIds, setKnowledgeBaseIds] = useState<string[]>(findKnowledge())
  const [groundingEntryIds, setGroundingEntryIds] = useState<string[]>(seed?.groundingEntryIds || state.knowledgeBases.filter(item => findKnowledge().includes(item.id)).flatMap(item => item.entries.filter(entry => entry.status === 'Approved')).map(entry => entry.id))
  const [imageLibraryId, setImageLibraryId] = useState(seed?.imageLibraryId || state.imageLibraries.find(item => item.name === seed?.imageLibrary)?.id || state.imageLibraries[0]?.id || '')
  const initialImageIds = seed?.imageIds || state.imageLibraries.find(item => item.id === imageLibraryId)?.selectedImageIds || []
  const [imageIds, setImageIds] = useState<string[]>(initialImageIds)
  const [imagesPerArticle, setImagesPerArticle] = useState(seed?.imagesPerArticle ?? 1)
  const [model, setModel] = useState(seed?.model || 'Local simulation')
  const [target, setTarget] = useState(seed?.target || 10)
  const keywordSet = state.keywordSets.find(item => item.id === keywordSetId)
  const bodyInstruction = state.instructions.find(item => item.id === bodyInstructionId)
  const titleInstruction = state.instructions.find(item => item.id === titleInstructionId)
  const imageLibrary = state.imageLibraries.find(item => item.id === imageLibraryId)
  const selectedKnowledgeBases = state.knowledgeBases.filter(item => knowledgeBaseIds.includes(item.id))
  const availableEntries = selectedKnowledgeBases.flatMap(item => item.entries)
  const selectedEntries = availableEntries.filter(entry => groundingEntryIds.includes(entry.id))
  const toggleKnowledge = (id: string) => {
    const next = knowledgeBaseIds.includes(id) ? knowledgeBaseIds.filter(item => item !== id) : [...knowledgeBaseIds, id]
    setKnowledgeBaseIds(next)
    const nextEntries = state.knowledgeBases.filter(item => next.includes(item.id)).flatMap(item => item.entries.filter(entry => entry.status === 'Approved')).map(entry => entry.id)
    setGroundingEntryIds(current => current.filter(entryId => nextEntries.includes(entryId)).length ? current.filter(entryId => nextEntries.includes(entryId)) : nextEntries)
  }
  const toggleImageLibrary = (id: string) => { setImageLibraryId(id); const library = state.imageLibraries.find(item => item.id === id); setImageIds(library?.selectedImageIds?.length ? library.selectedImageIds : (library?.images || []).map(image => image.id)) }
  const toggleEntry = (id: string) => setGroundingEntryIds(current => current.includes(id) ? current.filter(entryId => entryId !== id) : [...current, id])
  const toggleImage = (id: string) => setImageIds(current => current.includes(id) ? current.filter(imageId => imageId !== id) : [...current, id])
  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (mode === 'inspect') return
    if (!name.trim() || !keywordSet || !knowledgeBaseIds.length) return
    const baseTask: CreationTask = { id: mode === 'edit' && seed ? seed.id : uid('ct'), name: name.trim(), keyword: keywordSet.name, questionCount: keywordSet.questionCount, writingInstruction: bodyInstruction?.title || 'Reusable article instruction', titleInstruction: titleInstruction?.title || 'Reusable title instruction', knowledgeBase: selectedKnowledgeBases.map(item => item.name).join(', '), imageLibrary: imageLibrary?.name || 'No image library', generated: seed?.generated || 0, target: Math.max(1, target), status: seed?.status || 'Ready', updated: 'just now', model: model.trim() || 'Local simulation', localOnly: true, keywordSetId, writingInstructionId: bodyInstructionId, titleInstructionId, knowledgeBaseIds, knowledgeBases: selectedKnowledgeBases.map(item => item.name), groundingEntryIds, imageLibraryId, imageCount: imageIds.length, imageIds, imagesPerArticle: Math.max(0, imagesPerArticle) }
    if (mode === 'edit' && seed) {
      const log: CreationLog = { id: uid('log'), time: 'just now', message: 'Task configuration updated locally.', tone: 'info' }
      const updated: CreationTask = { ...seed, ...baseTask, generated: seed.generated, status: seed.status, created: seed.created, logs: [...(seed.logs || []), log] }
      patch({ creationTasks: state.creationTasks.map(item => item.id === seed.id ? updated : item) }); notify(tr('Creation task updated locally')); onClose(); return
    }
    const isDuplicate = mode === 'duplicate'
    const task: CreationTask = { ...baseTask, generated: 0, status: 'Ready', updated: 'just now', created: 'just now', logs: [{ id: uid('log'), time: 'just now', message: isDuplicate ? 'Duplicated task configuration saved locally; original task continues independently.' : 'Task configuration created locally; awaiting simulated execution.', tone: 'info' }] }
    patch({ creationTasks: [task, ...state.creationTasks] }); notify(tr(isDuplicate ? 'Creation task duplicated locally' : 'Creation task created locally')); onClose()
  }
  const isReadOnly = mode === 'inspect'
  const displayedName = isReadOnly ? (seed?.name || '') : name
  const modalTitle = mode === 'inspect' ? tr('Inspect creation task') : mode === 'edit' ? tr('Edit creation task') : tr('Create automatic task')
  const submitLabel = isReadOnly ? tr('Close') : mode === 'edit' ? tr('Save changes') : mode === 'duplicate' ? tr('Create duplicated task') : tr('Create task')
  return <Modal title={modalTitle} onClose={onClose} headerAction={isReadOnly ? <button type="button" className="button button-primary button-small" onClick={() => { if (seed) setName(seed.name); setMode('edit') }}><PenLine size={14} /> {tr('Edit')}</button> : undefined}><form className="creation-form" onSubmit={submit}><div className="creation-form-grid"><label>{tr('Task name')}<input autoFocus disabled={isReadOnly} value={displayedName} onChange={event => setName(event.target.value)} placeholder={tr('e.g. Operations guide batch')} /></label><label>{tr('Model label')}<select disabled={isReadOnly} value={model} onChange={event => setModel(event.target.value)}><option value="Local simulation">{tr('Local simulation')}</option>{models.map(item => <option key={item} value={item}>{item}</option>)}{realModels.map(item => <option key={item} value={item}>{item} · {tr('live agent')}</option>)}</select></label><label>{tr('Keyword Set / question pool')}<select disabled={isReadOnly} value={keywordSetId} onChange={event => setKeywordSetId(event.target.value)}>{state.keywordSets.map(item => <option value={item.id} key={item.id}>{tr(item.name)} · {item.questionCount} {tr('questions')}</option>)}</select>{keywordSet && <small>{keywordSet.prompts.length} {tr('sample prompts')} · {tr('reused for each simulated batch')}</small>}</label><label>{tr('Target quantity')}<input type="number" min="1" disabled={isReadOnly} value={target} onChange={event => setTarget(Number(event.target.value) || 1)} /></label><label>{tr('Writing instruction · body')}<select disabled={isReadOnly} value={bodyInstructionId} onChange={event => setBodyInstructionId(event.target.value)}>{state.instructions.filter(item => item.group === 'Article').map(item => <option value={item.id} key={item.id}>{tr(item.title)}</option>)}</select>{bodyInstruction && <small>{tr(bodyInstruction.description)}</small>}</label><label>{tr('Title instruction')}<select disabled={isReadOnly} value={titleInstructionId} onChange={event => setTitleInstructionId(event.target.value)}>{state.instructions.filter(item => item.group === 'Title').map(item => <option value={item.id} key={item.id}>{tr(item.title)}</option>)}</select>{titleInstruction && <small>{tr(titleInstruction.description)}</small>}</label></div><section className="creation-choice-section"><div className="section-row"><div><h3>{tr('Knowledge Bases')}</h3><p>{tr('Choose one or more bases, then select the entries used for grounding.')}</p></div><span className="count-label">{knowledgeBaseIds.length} {tr('selected')}</span></div><div className="creation-choice-grid">{state.knowledgeBases.map(item => <label className={`choice-card ${knowledgeBaseIds.includes(item.id) ? 'selected' : ''} ${isReadOnly ? 'readonly' : ''}`} key={item.id}><input type="checkbox" disabled={isReadOnly} checked={knowledgeBaseIds.includes(item.id)} onChange={() => toggleKnowledge(item.id)} /><Database size={15} /><span><strong>{tr(item.name)}</strong><small>{item.entries.length} {tr('entries')}</small></span></label>)}</div>{selectedKnowledgeBases.length > 0 && <div className="grounding-choice-list"><strong>{tr('Grounding entries')}</strong>{availableEntries.map(entry => <label key={entry.id}><input type="checkbox" disabled={isReadOnly} checked={groundingEntryIds.includes(entry.id)} onChange={() => toggleEntry(entry.id)} /> <span className="kb-category-chip">{tr(entry.category)}</span><span>{tr(entry.title)}</span></label>)}{!availableEntries.length && <small>{tr('Selected knowledge bases have no entries yet.')}</small>}</div>}</section><section className="creation-choice-section"><div className="section-row"><div><h3>{tr('Image Library')}</h3><p>{tr('Use selected local images as visible task context; the task stores IDs only.')}</p></div><span className="count-label">{imageIds.length} {tr('selected')}</span></div><div className="creation-choice-grid">{state.imageLibraries.map(item => <label className={`choice-card ${imageLibraryId === item.id ? 'selected' : ''} ${isReadOnly ? 'readonly' : ''}`} key={item.id}><input type="radio" name="image-library" disabled={isReadOnly} checked={imageLibraryId === item.id} onChange={() => toggleImageLibrary(item.id)} /><Image size={15} /><span><strong>{tr(item.name)}</strong><small>{item.images.length} {tr('images')}</small></span></label>)}</div>{imageLibrary && <div className="image-picker-row">{imageLibrary.images.slice(0, 8).map(image => <label key={image.id} title={image.name}><input type="checkbox" disabled={isReadOnly} checked={imageIds.includes(image.id)} onChange={() => toggleImage(image.id)} /><span className="mini-image-placeholder"><Image size={13} /></span><small>{tr(image.name)}</small></label>)}{!imageLibrary.images.length && <span>{tr('This library has no local images.')}</span>}</div>}<label className="inline-number-field">{tr('Images per article')}<input type="number" min="0" max="10" disabled={isReadOnly} value={imagesPerArticle} onChange={event => setImagesPerArticle(Number(event.target.value) || 0)} /></label></section><section className="creation-local-options"><ShieldCheck size={16} /><div><strong>{tr(isReadOnly ? 'Configuration summary' : 'Local-only options')}</strong><p>{tr(isReadOnly ? 'Live model, proxy, and grounding are configured for this task. Edits require closing inspect and reopening Edit.' : 'Simulated tasks stay inside the browser. Tasks using a real model call the local proxy, which forwards to the upstream provider; no secret, upload, or real publishing action touches the browser.')}</p></div><span className="status-pill active">{tr('Enabled')}</span></section><div className="creation-preview"><strong>{tr('Reusable prompt preview')}</strong><p>{tr(bodyInstruction?.description || 'The selected writing instruction will be reused for every question in the pool.')} {tr(titleInstruction?.description || '')}</p></div><div className="modal-foot"><span><span className="status-dot" /> {isReadOnly ? tr('Read-only view · click Edit to make changes') : tr('Stored in browser only')}</span><div><button type="button" className="button button-outline" onClick={onClose}>{isReadOnly ? tr('Close') : tr('Cancel')}</button>{!isReadOnly && <button type="submit" className="button button-primary" disabled={!name.trim() || !keywordSet || !knowledgeBaseIds.length}><Check size={15} /> {submitLabel}</button>}</div></div></form></Modal>
}

export function InstructionModal({ initialMode, seed, state, patch, onClose, notify }: { initialMode: 'create' | 'inspect'; seed: WritingInstruction | null; state: AppState; patch: (next: Partial<AppState>) => void; onClose: () => void; notify: (message: string) => void }) {
  const { t: tr } = useTranslation()
  const [mode, setMode] = useState<'create' | 'edit' | 'inspect'>(initialMode)
  const isReadOnly = mode === 'inspect'
  const [title, setTitle] = useState(seed?.title || '')
  const [description, setDescription] = useState(seed?.description || '')
  const [group, setGroup] = useState<WritingInstruction['group']>(seed?.group || 'Article')
  const [status, setStatus] = useState<WritingInstruction['status']>(seed?.status || 'Draft')
  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (isReadOnly) return
    const safeTitle = title.trim()
    if (!safeTitle) return
    if (mode === 'edit' && seed) {
      patch({ instructions: state.instructions.map(item => item.id === seed.id ? { ...item, title: safeTitle, description, group, status, updated: formatDate() } : item) })
      notify(tr('Writing instruction updated locally'))
      onClose()
      return
    }
    patch({ instructions: [{ id: uid('wi'), title: safeTitle, group, description: description || 'New reusable writing guidance.', updated: formatDate(), status }, ...state.instructions] })
    notify(tr('Writing instruction created locally'))
    onClose()
  }
  const modalTitle = mode === 'inspect' ? tr('Inspect writing instruction') : mode === 'edit' ? tr('Edit writing instruction') : tr('Create writing instruction')
  const submitLabel = mode === 'edit' ? tr('Save changes') : tr('Create instruction')
  const usage = seed ? state.creationTasks.filter(task => task.writingInstructionId === seed.id || task.titleInstructionId === seed.id) : []
  return <Modal title={modalTitle} onClose={onClose} headerAction={isReadOnly ? <button type="button" className="button button-primary button-small" onClick={() => setMode('edit')}><PenLine size={14} /> {tr('Edit')}</button> : undefined}><form className="creation-form" onSubmit={submit}><div className="creation-form-grid"><label>{tr('Title')}<input autoFocus disabled={isReadOnly} value={title} onChange={event => setTitle(event.target.value)} placeholder={tr('e.g. Long-form standard')} /></label><label>{tr('Group')}<select disabled={isReadOnly} value={group} onChange={event => setGroup(event.target.value as WritingInstruction['group'])}><option>{tr('Article')}</option><option>{tr('Title')}</option><option>{tr('Traffic Replication')}</option></select></label><label>{tr('Status')}<select disabled={isReadOnly} value={status} onChange={event => setStatus(event.target.value as WritingInstruction['status'])}><option>{tr('Active')}</option><option>{tr('Draft')}</option></select></label></div><label className="creation-form-field">{tr('Description')}<textarea rows={5} disabled={isReadOnly} value={description} onChange={event => setDescription(event.target.value)} placeholder={tr('Describe the body structure, tone, and editorial behavior.')} /></label>{seed && <section className="creation-preview"><strong>{tr('Used by')}</strong><p>{usage.length ? tr(`${usage.length} creation task${usage.length === 1 ? '' : 's'} reference this instruction`) : tr('No creation task uses this instruction yet.')}</p></section>}<div className="modal-foot"><span><span className="status-dot" /> {isReadOnly ? tr('Read-only view · click Edit to make changes') : tr('Stored in browser only')}</span><div><button type="button" className="button button-outline" onClick={onClose}>{isReadOnly ? tr('Close') : tr('Cancel')}</button>{!isReadOnly && <button type="submit" className="button button-primary" disabled={!title.trim()}><Check size={15} /> {submitLabel}</button>}</div></div></form></Modal>
}

export function ArticlePage({ state, onDetail }: { state: AppState; onDetail: (item: Article) => void }) { const { t: tr } = useTranslation(); const [search, setSearch] = useState(''); const [status, setStatus] = useState('All statuses'); const [task, setTask] = useState('All tasks'); const [page, setPage] = useState(1); const tasks = [...new Set(state.articles.map(item => item.task))]; const filtered = state.articles.filter(item => (status === 'All statuses' || item.status === status) && (task === 'All tasks' || item.task === task) && `${item.title} ${item.keyword} ${item.model}`.toLowerCase().includes(search.toLowerCase())); const shown = filtered.slice((page - 1) * 4, page * 4); return <div className="content-stack"><Toolbar search={search} setSearch={value => { setSearch(value); setPage(1) }} selects={<><select aria-label={tr("Filter by article task")} value={task} onChange={e => { setTask(e.target.value); setPage(1) }}><option value="All tasks">{tr("All tasks")}</option>{tasks.map(item => <option key={item} value={item}>{tr(item)}</option>)}</select><select aria-label={tr("Filter by article status")} value={status} onChange={e => { setStatus(e.target.value); setPage(1) }}><option value="All statuses">{tr("All statuses")}</option><option value="Draft">{tr("Draft")}</option><option value="Review">{tr("Review")}</option><option value="Published">{tr("Published")}</option><option value="Scheduled">{tr("Scheduled")}</option></select></>} /><section className="card table-card"><div className="table-scroll"><table><thead><tr><th>{tr("Article")}</th><th>{tr("Task")}</th><th>{tr("Model")}</th><th>{tr("Status")}</th><th>{tr("Publication")}</th><th>{tr("Words")}</th><th>{tr("Date")}</th></tr></thead><tbody>{shown.map(item => <tr key={item.id}><td><button className="table-title-button" onClick={() => onDetail(item)}>{tr(item.title)}</button><small className="table-subtitle">{tr(item.keyword)}</small></td><td>{tr(item.task)}</td><td><span className="model-badge">{item.model}</span></td><td><span className={`status-pill ${item.status.toLowerCase()}`}>{tr(item.status)}</span></td><td>{tr(item.channel)}</td><td>{item.wordCount.toLocaleString()}</td><td>{tr(item.date)}</td></tr>)}</tbody></table></div><div className="table-footer"><span>{filtered.length} {tr("articles · model attribution is simulated")}</span><div className="pagination"><button className="icon-button" disabled={page === 1} aria-label={tr("Previous page")} onClick={() => setPage(value => Math.max(1, value - 1))}>‹</button><span>{tr(`Page ${page}`)}</span><button className="icon-button" disabled={page * 4 >= filtered.length} aria-label={tr("Next page")} onClick={() => setPage(value => value + 1)}>›</button></div></div></section></div> }

export function PublishingPage({ state, patch, onCreate, onConfirm, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; onCreate: () => void; onConfirm: (confirmation: { title: string; action: () => void }) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const duplicate = (task: PublishingTask) => { patch({ publishingTasks: [...state.publishingTasks, { ...task, id: uid('pub'), name: `${task.name} copy`, status: 'Paused' }] }); notify(tr('Publishing task duplicated locally')) }; const remove = (task: PublishingTask) => onConfirm({ title: `Delete ${task.name}?`, action: () => { patch({ publishingTasks: state.publishingTasks.filter(item => item.id !== task.id) }); notify(tr('Publishing task deleted locally')) } }); return <div className="content-stack"><PublisherPanel articles={state.articles} notify={notify} /><section className="notice-banner compact-banner"><div className="notice-mark"><Cloud size={17} /></div><div><strong>{tr("Owned-channel publishing is simulated")}</strong><p>{tr("No account is connected. These queues only demonstrate configuration and status management.")}</p></div><button className="button button-primary" onClick={onCreate}><Plus size={15} /> {tr("New media task")}</button></section><section className="card table-card"><div className="table-toolbar"><div><h2>{tr("Personal Media")}</h2><p className="toolbar-subtitle">{tr("Article pools, channel rules, and last local run")}</p></div><span className="simulated-label"><span className="status-dot" /> {tr("Local records")}</span></div><div className="table-scroll"><table><thead><tr><th>{tr("Task")}</th><th>{tr("Article pool")}</th><th>{tr("Account / channel")}</th><th>{tr("Limit")}</th><th>{tr("Rules")}</th><th>{tr("Status")}</th><th>{tr("Last run")}</th><th>{tr("Actions")}</th></tr></thead><tbody>{state.publishingTasks.map(task => <tr key={task.id}><td><strong className="table-title">{tr(task.name)}</strong></td><td>{tr(task.pool)}</td><td><span className="channel-badge">{tr(task.account)}</span> <span className="channel-badge muted">{tr(task.channel)}</span></td><td>{task.limit} {tr("/ run")}</td><td><span className="rule-chip">{task.deduplication ? tr('Dedup') : tr('No dedup')}</span><span className="rule-chip">{task.aiDisclosure ? tr('AI disclosed') : tr('No disclosure')}</span></td><td><span className={`status-pill ${task.status.toLowerCase()}`}>{tr(task.status)}</span></td><td>{tr(task.lastRun)}</td><td><div className="row-actions"><button className="icon-button" aria-label={tr(`Duplicate ${task.name}`)} onClick={() => duplicate(task)}><MoreHorizontal size={15} /></button><button className="icon-button danger-icon" aria-label={tr(`Delete ${task.name}`)} onClick={() => remove(task)}><Trash2 size={15} /></button></div></td></tr>)}</tbody></table></div></section></div> }

export function OperationsPage({ route, state, patch, notify }: { route: Route; state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) {
  if (route === 'records') return <RecordsSurface state={state} />
  if (route === 'accounts') return <AccountsSurface state={state} patch={patch} notify={notify} />
  if (route === 'website-media') return <WebsiteSurface state={state} patch={patch} notify={notify} />
  if (route === 'influencers') return <InfluencersSurface state={state} patch={patch} notify={notify} />
  return <SeoSurface state={state} patch={patch} notify={notify} />
}

function OperationsBanner({ title, text }: { title: string; text: string }) { const { t: tr } = useTranslation(); return <section className="notice-banner compact-banner"><div className="notice-mark"><ShieldCheck size={17} /></div><div><strong>{title}</strong><p>{text}</p></div><span className="status-pill draft">{tr("Simulated · not connected")}</span></section> }

function RecordsSurface({ state }: { state: AppState }) { const { t: tr } = useTranslation(); const [search, setSearch] = useState(''); const [type, setType] = useState('All types'); const [selected, setSelected] = useState<OperationsRecord | null>(null); const records = state.records.filter(item => (type === 'All types' || item.type === type) && `${item.summary} ${item.owner}`.toLowerCase().includes(search.toLowerCase())); return <div className="content-stack"><OperationsBanner title={tr("Local operating records")} text={tr("A reviewable activity trail for the simulated workflow. No external audit log is written.")} /><Toolbar search={search} setSearch={setSearch} selects={<select aria-label={tr("Filter record type")} value={type} onChange={event => setType(event.target.value)}><option value="All types">{tr("All types")}</option><option value="Generation">{tr("Generation")}</option><option value="Review">{tr("Review")}</option><option value="Publishing">{tr("Publishing")}</option><option value="Validation">{tr("Validation")}</option></select>} /><section className="card table-card"><div className="table-scroll"><table><thead><tr><th>{tr("Event")}</th><th>{tr("Type")}</th><th>{tr("Owner")}</th><th>{tr("Status")}</th><th>{tr("Date")}</th></tr></thead><tbody>{records.map(record => <tr key={record.id} tabIndex={0} onClick={() => setSelected(record)} onKeyDown={event => event.key === 'Enter' && setSelected(record)}><td><strong className="table-title">{tr(record.summary)}</strong></td><td><span className="model-badge">{tr(record.type)}</span></td><td>{tr(record.owner)}</td><td><span className={`status-pill ${record.status === 'Complete' ? 'completed' : record.status === 'In review' ? 'review' : 'ready'}`}>{tr(record.status)}</span></td><td>{tr(record.date)}</td></tr>)}</tbody></table></div><div className="table-footer"><span>{records.length} {tr("local records")}</span><span>{tr("Click a record for a detail note")}</span></div></section>{selected && <section className="card selected-record"><div><span className="eyebrow">{tr("RECORD DETAIL")}</span><h2>{tr(selected.summary)}</h2><p>{tr(selected.type)} · {tr("owned by")} {tr(selected.owner)} · {tr(selected.date)}</p></div><span className="status-pill active">{tr(selected.status)}</span></section>}</div> }

function AccountsSurface({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [search, setSearch] = useState(''); const [draft, setDraft] = useState(''); const accounts = state.accounts.filter(item => `${item.name} ${item.channel} ${item.owner}`.toLowerCase().includes(search.toLowerCase())); const toggle = (account: AccountConfig) => { patch({ accounts: state.accounts.map(item => item.id === account.id ? { ...item, status: item.status === 'Configured' ? 'Not connected' : 'Configured' } : item) }); notify(tr(`${account.name} marked ${account.status === 'Configured' ? 'not connected' : 'configured'} locally`)) }; const add = () => { if (!draft.trim()) return; patch({ accounts: [{ id: uid('acct'), name: draft.trim(), type: 'CMS', channel: 'Website', status: 'Not connected', owner: 'Editorial team' }, ...state.accounts] }); setDraft(''); notify(tr('Account placeholder added locally')) }; return <div className="content-stack"><OperationsBanner title={tr("Account configuration placeholders")} text={tr("Configure channel ownership without storing credentials. No login or secret fields exist in this demo.")} /><Toolbar search={search} setSearch={setSearch} action={<div className="inline-create"><input aria-label={tr("New account placeholder")} value={draft} onChange={event => setDraft(event.target.value)} placeholder={tr("Account placeholder name")} /><button className="button button-primary" onClick={add}><Plus size={14} /> {tr("Add placeholder")}</button></div>} /><div className="ops-card-grid">{accounts.map(account => <article className="card ops-card" key={account.id}><div className="ops-card-top"><span className="ops-icon cyan"><Cloud size={17} /></span><span className={`status-pill ${account.status === 'Configured' ? 'active' : 'draft'}`}>{tr(account.status)}</span></div><h3>{tr(account.name)}</h3><p>{tr(account.type)} · {tr(account.channel)}</p><small>{tr("Owner:")} {tr(account.owner)}</small><button className="button button-small button-outline" onClick={() => toggle(account)}>{account.status === 'Configured' ? tr('Mark not connected') : tr('Configure locally')}</button></article>)}</div></div> }

function WebsiteSurface({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [name, setName] = useState(''); const [domain, setDomain] = useState(''); const [approval, setApproval] = useState<WebsiteChannel['approval']>('Manual'); const toggle = (channel: WebsiteChannel) => { patch({ websiteChannels: state.websiteChannels.map(item => item.id === channel.id ? { ...item, status: item.status === 'Ready' ? 'Draft' : 'Ready' } : item) }); notify(tr(`${channel.name} is now ${channel.status === 'Ready' ? 'draft' : 'ready'} locally`)) }; const add = () => { if (!name.trim() || !domain.trim()) return; patch({ websiteChannels: [{ id: uid('site'), name: name.trim(), domain: domain.trim(), contentType: 'Long-form article', approval, status: 'Draft', updated: 'just now' }, ...state.websiteChannels] }); setName(''); setDomain(''); notify(tr('Website channel added locally')) }; return <div className="content-stack"><OperationsBanner title={tr("Website media channels")} text={tr("Plan owned-site destinations and approval rules. The domain is display data only; no request is made.")} /><section className="card inline-form-card"><div><h2>{tr("Add website channel")}</h2><p>{tr("Use a safe placeholder path; credentials are never requested.")}</p></div><div className="inline-form"><input aria-label={tr("Website channel name")} value={name} onChange={event => setName(event.target.value)} placeholder={tr("Channel name")} /><input aria-label={tr("Website path")} value={domain} onChange={event => setDomain(event.target.value)} placeholder={tr("example.local/resources")} /><select aria-label={tr("Approval mode")} value={approval} onChange={event => setApproval(event.target.value as WebsiteChannel['approval'])}><option value="Manual">{tr("Manual")}</option><option value="Auto review">{tr("Auto review")}</option></select><button className="button button-primary" onClick={add}><Plus size={14} /> {tr("Add channel")}</button></div></section><div className="ops-card-grid">{state.websiteChannels.map(channel => <article className="card ops-card" key={channel.id}><div className="ops-card-top"><span className="ops-icon cobalt"><Globe2 size={17} /></span><span className={`status-pill ${channel.status === 'Ready' ? 'active' : 'draft'}`}>{tr(channel.status)}</span></div><h3>{tr(channel.name)}</h3><p>{tr(channel.domain)}</p><small>{tr(channel.contentType)} · {tr(channel.approval)} {tr("approval")} · {tr("Updated")} {tr(channel.updated)}</small><button className="button button-small button-outline" onClick={() => toggle(channel)}>{tr(channel.status === 'Ready' ? 'Move to draft' : 'Mark ready')}</button></article>)}</div></div> }

function InfluencersSurface({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [search, setSearch] = useState(''); const [draft, setDraft] = useState(''); const partners = state.influencers.filter(item => `${item.name} ${item.focus} ${item.stage}`.toLowerCase().includes(search.toLowerCase())); const advance = (partner: InfluencerPartner) => { const stages: InfluencerPartner['stage'][] = ['Research', 'Briefed', 'Approved']; const next = stages[(stages.indexOf(partner.stage) + 1) % stages.length]; patch({ influencers: state.influencers.map(item => item.id === partner.id ? { ...item, stage: next } : item) }); notify(tr(`${partner.name} moved to ${next} locally`)) }; const add = () => { if (!draft.trim()) return; patch({ influencers: [{ id: uid('inf'), name: draft.trim(), focus: 'New partner research', stage: 'Research', audience: 'Unverified', note: 'Local planning note' }, ...state.influencers] }); setDraft(''); notify(tr('Partner research record added locally')) }; return <div className="content-stack"><OperationsBanner title={tr("Partner distribution planning")} text={tr("Influencer records are planning notes only. No outreach, messaging, or contact data is stored.")} /><Toolbar search={search} setSearch={setSearch} action={<div className="inline-create"><input aria-label={tr("New partner name")} value={draft} onChange={event => setDraft(event.target.value)} placeholder={tr("Partner or publication")} /><button className="button button-primary" onClick={add}><Plus size={14} /> {tr("Add research record")}</button></div>} /><div className="ops-card-grid">{partners.map(partner => <article className="card ops-card" key={partner.id}><div className="ops-card-top"><span className="ops-icon violet"><Users size={17} /></span><span className={`status-pill ${partner.stage === 'Approved' ? 'active' : partner.stage === 'Briefed' ? 'review' : 'draft'}`}>{tr(partner.stage)}</span></div><h3>{tr(partner.name)}</h3><p>{tr(partner.focus)} · {tr(partner.audience)}</p><small>{tr(partner.note)}</small><button className="button button-small button-outline" onClick={() => advance(partner)}>{tr("Advance stage")}</button></article>)}</div></div> }

function SeoSurface({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [filter, setFilter] = useState('All checks'); const checks = state.seoChecks.filter(item => filter === 'All checks' || item.status === filter); const cycle = (check: SeoCheck) => { const statuses: SeoCheck['status'][] = ['Healthy', 'Needs review', 'Opportunity']; const next = statuses[(statuses.indexOf(check.status) + 1) % statuses.length]; patch({ seoChecks: state.seoChecks.map(item => item.id === check.id ? { ...item, status: next } : item) }); notify(tr(`${check.area} status changed to ${next}`)) }; return <div className="content-stack"><OperationsBanner title={tr("Official-site SEO workspace")} text={tr("Use these local checks to plan crawlability, schema, linking, and freshness work. This is not a live site audit.")} /><Toolbar selects={<select aria-label={tr("Filter SEO check status")} value={filter} onChange={event => setFilter(event.target.value)}><option value="All checks">{tr("All checks")}</option><option value="Healthy">{tr("Healthy")}</option><option value="Needs review">{tr("Needs review")}</option><option value="Opportunity">{tr("Opportunity")}</option></select>} /><div className="seo-grid">{checks.map(check => <article className="card seo-card" key={check.id}><div className="ops-card-top"><span className="eyebrow">{tr(check.area).toUpperCase()}</span><span className={`status-pill ${check.status === 'Healthy' ? 'active' : check.status === 'Needs review' ? 'review' : 'draft'}`}>{tr(check.status)}</span></div><div className="seo-score"><strong>{check.score}</strong><div className="progress"><span style={{ width: `${check.score}%` }} /></div></div><p>{tr(check.note)}</p><small>{tr("Updated")} {tr(check.updated)}</small><button className="button button-small button-outline" onClick={() => cycle(check)}>{tr("Cycle status")}</button></article>)}</div></div> }

function InfoPage({ route, navigate }: { route: Route; navigate: (route: Route) => void }) { const { t: tr } = useTranslation(); const info: Record<string, { icon: IconType; title: string; bullets: string[]; action?: Route }> = { records: { icon: ClipboardList, title: 'Records', bullets: ['Review local state changes from generation, review, and publishing surfaces.', 'Future integrations can map each record to an external audit trail.', 'This demo intentionally keeps the trail in browser storage.'] }, accounts: { icon: UserRound, title: 'Accounts', bullets: ['No social, CMS, or email account is connected in this demo.', 'Use this destination to plan account ownership and publishing permissions.', 'Connection controls are intentionally informative only.'] }, 'website-media': { icon: Globe2, title: 'Website Media', bullets: ['Define site channels, slug rules, and content ownership before connecting a CMS.', 'Pair a website channel with a Personal Media task when the workflow is ready.', 'The current workspace never sends a network request.'], action: 'personal-media' }, influencers: { icon: Users, title: 'Influencers', bullets: ['Keep partner distribution separate from owned-channel publishing.', 'Capture campaign briefs, creator fit, and approval checkpoints here in a future version.', 'No outreach or messaging is performed by this local demo.'] }, 'official-seo': { icon: Search, title: 'Official-site SEO', bullets: ['Track internal-linking, schema, crawlability, and freshness work around owned content.', 'Use model validation to inspect whether the intended answer is being recalled.', 'The readiness notes here are planning guidance, not a live site audit.'], action: 'model-validation' } }; const item = info[route] || info.records; return <div className="content-stack"><section className="info-hero card"><span className="info-hero-icon"><item.icon size={25} /></span><div><span className="eyebrow">{tr("INFORMATIVE DESTINATION")}</span><h2>{tr(item.title)}</h2><p>{tr("This surface is part of the operating model and is intentionally presented without an external connection.")}</p></div><span className="status-pill draft">{tr("Not connected")}</span></section><div className="info-grid">{item.bullets.map((bullet, index) => <article className="card info-card" key={bullet}><span>{String(index + 1).padStart(2, '0')}</span><p>{tr(bullet)}</p></article>)}</div>{item.action && <button className="button button-primary" onClick={() => navigate(item.action!)}>{tr("Open related workflow")} <ArrowUpRight size={15} /></button>}</div> }

function ValidationPage({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [model, setModel] = useState('All models'); const [search, setSearch] = useState(''); const [tab, setTab] = useState('All platforms'); const [running, setRunning] = useState(false); const filtered = state.validationResults.filter(item => (model === 'All models' || item.model === model) && (tab === 'All platforms' || item.platform === tab) && item.keyword.toLowerCase().includes(search.toLowerCase())); const run = () => { setRunning(true); window.setTimeout(() => { setRunning(false); notify(tr('Validation task completed locally')); patch({ validationResults: state.validationResults.map(item => item.id === 'vr-3' ? { ...item, score: Math.min(100, item.score + 4), status: 'Passed' } : item) }) }, 650) }; const exportCsv = () => { const header = 'keyword,model,platform,score,citations,responseTime,status,checked'; const body = filtered.map(item => [item.keyword, item.model, item.platform, item.score, item.citations, item.responseTime, item.status, item.checked].map(value => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\n'); const blob = new Blob([`${header}\n${body}`], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'geoflow-model-validation.csv'; anchor.click(); URL.revokeObjectURL(url); notify(tr('CSV exported from the local validation table')) }; return <div className="content-stack"><div className="kpi-grid compact-kpis"><Kpi label="Average quality" value="75.4" delta="+3.1 pts" icon={ShieldCheck} tone="green" /><Kpi label="Pass rate" value="67%" delta="4 of 6 checks" icon={Check} tone="cobalt" /><Kpi label="Citations / answer" value="4.5" delta="+0.8 this week" icon={BookOpen} tone="violet" /><Kpi label="Task queue" value="12" delta="Ready to run" icon={ClipboardList} tone="orange" /></div><div className="platform-tabs"><button className={tab === 'All platforms' ? 'active' : ''} onClick={() => setTab('All platforms')}>{tr("All platforms")}</button>{models.map(name => <button className={tab === name ? 'active' : ''} key={name} onClick={() => setTab(name)}>{name}</button>)}</div><Toolbar search={search} setSearch={setSearch} selects={<select aria-label={tr("Filter by model")} value={model} onChange={e => setModel(e.target.value)}><option value="All models">{tr("All models")}</option>{models.map(name => <option key={name}>{name}</option>)}</select>} action={<><button className="button button-outline" onClick={exportCsv}><Table2 size={15} /> {tr("Export CSV")}</button><button className="button button-primary" disabled={running} onClick={run}><RefreshCw size={15} className={running ? 'spin' : ''} /> {running ? tr('Running…') : tr('Run task')}</button></>} /><section className="card table-card"><div className="table-scroll"><table><thead><tr><th>{tr("Question / keyword")}</th><th>{tr("Platform")}</th><th>{tr("Quality")}</th><th>{tr("Citations")}</th><th>{tr("Response")}</th><th>{tr("Status")}</th><th>{tr("Checked")}</th></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><strong className="table-title">{item.keyword}</strong><small className="table-subtitle">{tr("Validation prompt")}</small></td><td><span className="model-badge">{item.platform}</span></td><td><div className="score-cell"><strong>{item.score}</strong><div className="progress"><span style={{ width: `${item.score}%` }} /></div></div></td><td>{item.citations}</td><td>{item.responseTime}</td><td><span className={`status-pill ${item.status.toLowerCase()}`}>{tr(item.status)}</span></td><td>{item.checked}</td></tr>)}</tbody></table></div><div className="table-footer"><span>{tr(`${filtered.length} validation results · simulated model output`)}</span><span className="task-destinations">{tr("Task center")} <ArrowUpRight size={13} /> {tr("Export destinations")} <ArrowUpRight size={13} /></span></div></section></div> }

export function ValidationPage2({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation();
  const [subview, setSubview] = useState<'Results' | 'Task Center' | 'Export Tasks'>('Results')
  const [model, setModel] = useState('All models'); const [search, setSearch] = useState(''); const [tab, setTab] = useState('All platforms'); const [draft, setDraft] = useState(''); const [running, setRunning] = useState<string | null>(null)
  const filtered = state.validationResults.filter(item => (model === 'All models' || item.model === model) && (tab === 'All platforms' || item.platform === tab) && item.keyword.toLowerCase().includes(search.toLowerCase()))
  const runTask = (task: ValidationTask) => { setRunning(task.id); patch({ validationTasks: state.validationTasks.map(item => item.id === task.id ? { ...item, status: 'Running', lastRun: 'Running locally' } : item) }); window.setTimeout(() => { setRunning(null); patch({ validationTasks: state.validationTasks.map(item => item.id === task.id ? { ...item, status: 'Completed', lastRun: 'just now' } : item), validationResults: state.validationResults.map(item => item.id === 'vr-3' ? { ...item, score: Math.min(100, item.score + 4), status: 'Passed' } : item) }); notify(tr(`${task.name} completed locally`)) }, 650) }
  const createTask = () => { if (!draft.trim()) return; const task: ValidationTask = { id: uid('vt'), name: draft.trim(), promptCount: 10, models: models.slice(0, 3), status: 'Ready', created: 'just now', lastRun: 'Never' }; patch({ validationTasks: [task, ...state.validationTasks] }); setDraft(''); notify(tr('Validation task created locally')) }
  const exportCsv = () => { const header = 'keyword,model,platform,score,citations,responseTime,status,checked'; const body = filtered.map(item => [item.keyword, item.model, item.platform, item.score, item.citations, item.responseTime, item.status, item.checked].map(value => `"${String(value).replace(/"/g, '""')}"`).join(',')).join('\n'); const blob = new Blob([`${header}\n${body}`], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'geo-model-validation.csv'; anchor.click(); URL.revokeObjectURL(url); const record: ExportTask = { id: uid('ex'), name: `Validation results · ${new Date().toLocaleDateString()}`, format: 'CSV', rows: filtered.length, status: 'Ready', created: 'just now', destination: 'Local download' }; patch({ exportTasks: [record, ...state.exportTasks] }); notify(tr('CSV export created locally')) }
  return <div className="content-stack"><div className="validation-subnav"><button className={subview === 'Results' ? 'active' : ''} onClick={() => setSubview('Results')}>{tr("Results")} <b>{state.validationResults.length}</b></button><button className={subview === 'Task Center' ? 'active' : ''} onClick={() => setSubview('Task Center')}>{tr("Task Center")} <b>{state.validationTasks.length}</b></button><button className={subview === 'Export Tasks' ? 'active' : ''} onClick={() => setSubview('Export Tasks')}>{tr("Export Tasks")} <b>{state.exportTasks.length}</b></button><span className="simulated-label"><span className="status-dot" /> {tr("Simulated model output")}</span></div>{subview === 'Results' && <><div className="kpi-grid compact-kpis"><Kpi label="Average quality" value="75.4" delta="+3.1 pts" icon={ShieldCheck} tone="green" /><Kpi label="Pass rate" value="67%" delta="4 of 6 checks" icon={Check} tone="cobalt" /><Kpi label="Citations / answer" value="4.5" delta="+0.8 this week" icon={BookOpen} tone="violet" /><Kpi label="Task queue" value={String(state.validationTasks.length)} delta="Local tasks" icon={ClipboardList} tone="orange" /></div><div className="platform-tabs"><button className={tab === 'All platforms' ? 'active' : ''} onClick={() => setTab('All platforms')}>{tr("All platforms")}</button>{models.map(name => <button className={tab === name ? 'active' : ''} key={name} onClick={() => setTab(name)}>{name}</button>)}</div><Toolbar search={search} setSearch={setSearch} selects={<select aria-label={tr("Filter by model")} value={model} onChange={e => setModel(e.target.value)}><option value="All models">{tr("All models")}</option>{models.map(name => <option key={name}>{name}</option>)}</select>} action={<><button className="button button-outline" onClick={exportCsv}><Table2 size={15} /> {tr("Export CSV")}</button><button className="button button-primary" onClick={() => setSubview('Task Center')}><Plus size={15} /> {tr("New task")}</button></>} /><section className="card table-card"><div className="table-scroll"><table><thead><tr><th>{tr("Question / keyword")}</th><th>{tr("Platform")}</th><th>{tr("Quality")}</th><th>{tr("Citations")}</th><th>{tr("Response")}</th><th>{tr("Status")}</th><th>{tr("Checked")}</th></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><strong className="table-title">{item.keyword}</strong><small className="table-subtitle">{tr("Validation prompt")}</small></td><td><span className="model-badge">{item.platform}</span></td><td><div className="score-cell"><strong>{item.score}</strong><div className="progress"><span style={{ width: `${item.score}%` }} /></div></div></td><td>{item.citations}</td><td>{item.responseTime}</td><td><span className={`status-pill ${item.status.toLowerCase()}`}>{tr(item.status)}</span></td><td>{item.checked}</td></tr>)}</tbody></table></div><div className="table-footer"><span>{tr(`${filtered.length} validation results`)}</span><span>{tr("CSV and results are local-only")}</span></div></section></>}{subview === 'Task Center' && <section className="content-stack"><section className="card inline-form-card"><div><span className="eyebrow">{tr("TASK CENTER · SIMULATED")}</span><h2>{tr("Create a local validation task")}</h2><p>{tr("Tasks never call a model; Run only updates seeded demo status and results.")}</p></div><div className="inline-form"><input aria-label={tr("Validation task name")} value={draft} onChange={event => setDraft(event.target.value)} placeholder={tr("e.g. Monthly brand sweep")} /><button className="button button-primary" onClick={createTask}><Plus size={14} /> {tr("Create task")}</button></div></section><div className="ops-card-grid">{state.validationTasks.map(task => <article className="card ops-card" key={task.id}><div className="ops-card-top"><span className="ops-icon violet"><ShieldCheck size={17} /></span><span className={`status-pill ${task.status === 'Completed' ? 'active' : task.status === 'Running' ? 'review' : 'draft'}`}>{tr(task.status)}</span></div><h3>{tr(task.name)}</h3><p>{task.promptCount} {tr("prompts")} · {task.models.join(', ')}</p><small>{tr("Created")} {tr(task.created)} · {tr("Last run")} {tr(task.lastRun)}</small><button className="button button-small button-outline" disabled={running === task.id} onClick={() => runTask(task)}>{running === task.id ? tr('Running locally…') : task.status === 'Completed' ? tr('Run again') : tr('Run simulated task')}</button></article>)}</div></section>}{subview === 'Export Tasks' && <section className="content-stack"><OperationsBanner title={tr("Local export tasks")} text={tr("Exports are browser-generated records. No remote destination or account is used.")} /><section className="card inline-form-card"><div><h2>{tr("Queue an export record")}</h2><p>{tr("Creates a simulated task entry for the current validation results.")}</p></div><button className="button button-primary" onClick={() => { const record: ExportTask = { id: uid('ex'), name: `Manual validation export · ${new Date().toLocaleDateString()}`, format: 'CSV', rows: state.validationResults.length, status: 'Queued', created: 'just now', destination: 'Local download' }; patch({ exportTasks: [record, ...state.exportTasks] }); notify(tr('Export task queued locally')) }}><Plus size={14} /> {tr("Create export task")}</button></section><section className="card table-card"><div className="table-scroll"><table><thead><tr><th>{tr("Export")}</th><th>{tr("Format")}</th><th>{tr("Rows")}</th><th>{tr("Status")}</th><th>{tr("Destination")}</th><th>{tr("Created")}</th></tr></thead><tbody>{state.exportTasks.map(task => <tr key={task.id}><td><strong className="table-title">{tr(task.name)}</strong></td><td>{task.format}</td><td>{task.rows}</td><td><span className={`status-pill ${task.status === 'Ready' ? 'active' : 'draft'}`}>{tr(task.status)}</span></td><td>{tr(task.destination)}</td><td>{tr(task.created)}</td></tr>)}</tbody></table></div></section></section>}</div>
}

export function PointsPage({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const [amount, setAmount] = useState('500'); const recharge = () => { const value = Math.max(0, Number(amount) || 0); if (!value) return notify(tr('Enter a points amount first')); const entry: LedgerEntry = { id: uid('led'), type: 'Recharge', detail: 'Simulated manual recharge', amount: value, balance: state.balance + value, date: 'just now' }; patch({ balance: state.balance + value, ledger: [entry, ...state.ledger] }); notify(tr(`${value.toLocaleString()} points simulated`)) }; return <div className="content-stack"><section className="points-hero card"><div><span className="eyebrow">{tr("AVAILABLE BALANCE")}</span><strong>{state.balance.toLocaleString()}</strong><p>{tr("Compute points are demo credits used to illustrate generation and validation consumption. They have no monetary value.")}</p></div><div className="recharge-box"><label>{tr("Simulate recharge")}<input inputMode="numeric" value={amount} onChange={e => setAmount(e.target.value)} /></label><button className="button button-primary" onClick={recharge}><Plus size={15} /> {tr("Add points")}</button><small>{tr("Explicitly simulated · no payment or billing")}</small></div></section><div className="info-grid points-explainer"><article className="card info-card"><span><BrainCircuit size={18} /></span><h3>{tr("Generation")}</h3><p>{tr("One question or article action can spend points in a real workspace. This demo only records sample usage.")}</p></article><article className="card info-card"><span><ShieldCheck size={18} /></span><h3>{tr("Validation")}</h3><p>{tr("Model checks use points in the simulated ledger to make operational costs visible.")}</p></article><article className="card info-card"><span><Info size={18} /></span><h3>{tr("Safe by design")}</h3><p>{tr("There is no payment provider, account connection, or external points system attached.")}</p></article></div><section className="card table-card"><div className="table-toolbar"><div><h2>{tr("Recent ledger")}</h2><p className="toolbar-subtitle">{tr("Local balance movements")}</p></div></div><div className="table-scroll"><table><thead><tr><th>{tr("Type")}</th><th>{tr("Detail")}</th><th>{tr("Amount")}</th><th>{tr("Balance")}</th><th>{tr("Date")}</th></tr></thead><tbody>{state.ledger.map(item => <tr key={item.id}><td><span className="ledger-type">{tr(item.type)}</span></td><td>{tr(item.detail)}</td><td className={item.amount > 0 ? 'positive' : ''}>{item.amount > 0 ? '+' : ''}{item.amount}</td><td>{item.balance}</td><td>{tr(item.date)}</td></tr>)}</tbody></table></div></section></div> }

export function AdminPage2({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation();
  type AdminView = 'users' | 'apiKeys' | 'llm' | 'points' | 'checks' | 'versions'
  const [selected, setSelected] = useState<AdminView>('users'); const [draft, setDraft] = useState('')
  const config = state.adminConfig
  const cards: { key: AdminView; label: string; value: string; detail: string; icon: IconType; tone: string }[] = [
    { key: 'users', label: 'Users', value: String(config.users.length), detail: 'Local team members', icon: Users, tone: 'cobalt' }, { key: 'apiKeys', label: 'API placeholders', value: String(config.apiKeys.length), detail: 'No real secrets', icon: KeyRound, tone: 'cyan' }, { key: 'llm', label: 'LLM config', value: String(config.llmConfigs.filter(item => item.enabled).length), detail: 'Enabled models', icon: Cpu, tone: 'violet' }, { key: 'points', label: 'Point rules', value: String(config.pointRules.length), detail: 'Demo cost rules', icon: WalletCards, tone: 'orange' }, { key: 'checks', label: 'Model checks', value: String(config.modelChecks.filter(item => item.status === 'Enabled').length), detail: 'Active schedules', icon: ShieldCheck, tone: 'green' }, { key: 'versions', label: 'Client versions', value: config.clientVersions[0]?.version || '—', detail: 'Current demo client', icon: Archive, tone: 'cobalt' },
  ]
  const addUser = () => { if (!draft.trim()) return; patch({ adminConfig: { ...config, users: [...config.users, { id: uid('usr'), name: draft.trim(), role: 'Reviewer', status: 'Invited', lastSeen: 'Never' }] } }); setDraft(''); notify(tr('Local user invitation added without sending email')) }
  const addKey = () => { if (!draft.trim()) return; patch({ adminConfig: { ...config, apiKeys: [...config.apiKeys, { id: uid('key'), label: draft.trim(), scope: 'Placeholder scope', status: 'Placeholder', created: 'just now' }] } }); setDraft(''); notify(tr('API placeholder added; no secret was requested or stored')) }
  const detail = selected === 'users' ? <><AdminDetailHead title={tr("Users")} note="Team records are local and do not create accounts." /><div className="inline-form"><input aria-label={tr("New local user")} value={draft} onChange={event => setDraft(event.target.value)} placeholder={tr("Reviewer name")} /><button className="button button-primary" onClick={addUser}><Plus size={14} /> {tr("Add invite")}</button></div><div className="admin-detail-list">{config.users.map(user => <div key={user.id}><span><strong>{tr(user.name)}</strong><small>{tr(user.role)} · {tr("last seen")} {tr(user.lastSeen)}</small></span><span className={`status-pill ${user.status === 'Active' ? 'active' : 'draft'}`}>{tr(user.status)}</span></div>)}</div></> : selected === 'apiKeys' ? <><AdminDetailHead title={tr("API placeholders")} note="These labels document future integration slots only; there is no secret input." /><div className="inline-form"><input aria-label={tr("New API placeholder")} value={draft} onChange={event => setDraft(event.target.value)} placeholder={tr("Placeholder label")} /><button className="button button-primary" onClick={addKey}><Plus size={14} /> {tr("Add placeholder")}</button></div><div className="admin-detail-list">{config.apiKeys.map(key => <div key={key.id}><span><strong>{tr(key.label)}</strong><small>{tr(key.scope)} · {tr("created")} {tr(key.created)}</small></span><span className="status-pill draft">{tr("Placeholder")}</span></div>)}</div></> : selected === 'llm' ? <><AdminDetailHead title={tr("LLM configuration")} note="Model settings are simulated labels, not credentials or network configuration." /><div className="admin-detail-list">{config.llmConfigs.map(item => <div key={item.id}><span><strong>{item.model}</strong><small>{tr("Mode")} {tr(item.mode)} · {tr("daily limit")} {item.dailyLimit}</small></span><button className={`status-pill ${item.enabled ? 'active' : 'paused'}`} onClick={() => patch({ adminConfig: { ...config, llmConfigs: config.llmConfigs.map(entry => entry.id === item.id ? { ...entry, enabled: !entry.enabled } : entry) } })}>{item.enabled ? tr('Enabled') : tr('Disabled')}</button></div>)}</div></> : selected === 'points' ? <><AdminDetailHead title={tr("Point rules")} note="Change only simulated costs; no billing or payment system is connected." /><div className="admin-detail-list">{config.pointRules.map(rule => <div key={rule.id}><span><strong>{tr(rule.action)}</strong><small>{tr(rule.note)}</small></span><label className="mini-number">{tr("Cost")} <input type="number" min="0" value={rule.cost} onChange={event => patch({ adminConfig: { ...config, pointRules: config.pointRules.map(entry => entry.id === rule.id ? { ...entry, cost: Number(event.target.value) || 0 } : entry) } })} /></label></div>)}</div></> : selected === 'checks' ? <><AdminDetailHead title={tr("Model check schedules")} note="Schedules update local statuses only." /><div className="admin-detail-list">{config.modelChecks.map(check => <div key={check.id}><span><strong>{check.model}</strong><small>{tr(check.cadence)} · {tr("last run")} {tr(check.lastRun)}</small></span><button className={`status-pill ${check.status === 'Enabled' ? 'active' : 'paused'}`} onClick={() => patch({ adminConfig: { ...config, modelChecks: config.modelChecks.map(entry => entry.id === check.id ? { ...entry, status: entry.status === 'Enabled' ? 'Paused' : 'Enabled' } : entry) } })}>{tr(check.status)}</button></div>)}</div></> : <><AdminDetailHead title={tr("Client versions")} note="Version records are informational demo data." /><div className="admin-detail-list">{config.clientVersions.map(version => <div key={version.id}><span><strong>{version.version}</strong><small>{tr(version.channel)} · {tr("released")} {tr(version.released)}</small></span><span className={`status-pill ${version.status === 'Current' ? 'active' : 'review'}`}>{tr(version.status)}</span></div>)}</div></>
  return <div className="content-stack"><section className="admin-hero card"><div><span className="eyebrow">{tr("ADMINISTRATOR VIEW · LOCAL SAFE MODE")}</span><h2>{tr("Keep the operating layer understandable.")}</h2><p>{tr("Configuration panels are interactive local records. No user account, API key, model credential, or external connection is created.")}</p></div><span className="admin-badge"><ShieldCheck size={16} /> {tr("Simulated only")}</span></section><div className="admin-grid">{cards.map(card => <button className={`card admin-card ${selected === card.key ? 'selected-admin' : ''}`} key={card.key} onClick={() => { setSelected(card.key); setDraft('') }}><span className={`admin-icon ${card.tone}`}><card.icon size={17} /></span><span className="admin-label">{tr(card.label)}</span><strong>{card.value}</strong><small>{tr(card.detail)}</small><ArrowUpRight size={15} /></button>)}</div><section className="card admin-detail-panel">{detail}</section><section className="card destination-panel"><div><span className="eyebrow">{tr("DESTINATION PANELS")}</span><h2>{tr("Configuration destinations")}</h2><p>{tr("Future connections can be added here without changing the content workflow.")}</p></div><div className="destination-list"><span><Settings2 size={15} /> {tr("Permissions")} <b>{tr("Informative")}</b></span><span><Cloud size={15} /> {tr("Integrations")} <b>{tr("Not connected")}</b></span><span><Palette size={15} /> {tr("Brand system")} <b>{tr("Local")}</b></span></div></section></div>
}

function AdminDetailHead({ title, note }: { title: string; note: string }) { const { t: tr } = useTranslation(); return <div className="admin-detail-head"><div><span className="eyebrow">{tr("SELECTED CONFIGURATION")}</span><h2>{tr(title)}</h2><p>{tr(note)}</p></div><span className="status-pill draft">{tr("Simulated")}</span></div> }

export function SettingsPage({ state, patch, notify }: { state: AppState; patch: (next: Partial<AppState>) => void; notify: (message: string) => void }) {
  const { t: tr } = useTranslation()
  const [name, setName] = useState('Ethan')
  const [agentStatus, setAgentStatus] = useState<AgentStatus | null>(null)
  const [agentTest, setAgentTest] = useState<'idle' | 'running' | 'ok' | 'error'>('idle')
  const [agentMessage, setAgentMessage] = useState<string>('')
  const refreshAgent = async () => { setAgentStatus(await fetchAgentStatus()) }
  useEffect(() => { refreshAgent() }, [])
  const testAgent = async () => {
    setAgentTest('running')
    setAgentMessage('')
    try {
      const response = await fetch('/api/anthropic/v1/messages', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'MiniMax-M3', max_tokens: 64, system: 'You are a connectivity check. Reply briefly.', messages: [{ role: 'user', content: 'Reply with the word "ok" and nothing else.' }] }),
      })
      if (!response.ok) {
        const err = await response.json().catch(() => ({ error: `HTTP ${response.status}` }))
        throw new Error(err.error || `HTTP ${response.status}`)
      }
      const payload = await response.json() as { content?: Array<{ type: string; text?: string }> }
      const text = (payload.content || []).filter(block => block.type === 'text').map(block => block.text || '').join('').trim()
      setAgentTest('ok')
      setAgentMessage(text || '(empty response)')
    } catch (err) {
      setAgentTest('error')
      setAgentMessage(err instanceof Error ? err.message : 'Unknown error')
    }
  }
  const reset = () => { patch({ ...defaultAppState, language: state.language }); notify(tr('Demo data reset to the original local snapshot')) }
  return <div className="content-stack"><section className="settings-grid"><div className="card settings-card"><span className="settings-icon"><Palette size={18} /></span><h2>{tr("Appearance")}</h2><p>{tr("Choose a comfortable workspace theme. The preference is stored locally in this browser.")}</p><div className="theme-choice"><button className={state.theme === 'light' ? 'selected' : ''} onClick={() => patch({ theme: 'light' })}><Sun size={16} /> {tr("Light")}</button><button className={state.theme === 'dark' ? 'selected' : ''} onClick={() => patch({ theme: 'dark' })}><Moon size={16} /> {tr("Dark")}</button></div></div><div className="card settings-card"><span className="settings-icon"><UserRound size={18} /></span><h2>{tr("User block")}</h2><p>{tr("Your local profile is only used for the shell greeting and has no login behavior.")}</p><label className="field-label">{tr("Display name")}<input value={name} onChange={e => setName(e.target.value)} /></label><button className="button button-outline" onClick={() => notify(tr(`Hello, ${name || 'there'} — profile saved locally`))}>{tr("Save profile")}</button></div></section><section className="card agent-panel"><div><span className="settings-icon"><Bot size={18} /></span><h2>{tr("Live writing agent")}</h2><p>{tr("Tasks that select a real model call the local proxy at :8787, which forwards to the configured Anthropic-compatible provider using the key in its environment. The key is never sent to the browser.") }</p></div><div className="agent-status-grid"><div><span>{tr("Provider")}</span><strong>{agentStatus ? (agentStatus.provider === 'unknown' ? tr('proxy offline') : agentStatus.provider) : tr('checking…')}</strong></div><div><span>{tr("API key")}</span><strong className={agentStatus?.configured ? 'positive' : 'muted'}>{agentStatus?.configured ? tr('configured') : tr('not set')}</strong></div><div><span>{tr("Last test")}</span><strong>{agentTest === 'idle' ? tr('not run') : agentTest === 'running' ? tr('running…') : agentTest === 'ok' ? tr('ok') : tr('failed')}</strong></div>{agentMessage && <div className="agent-message"><span>{tr("Sample reply")}</span><strong>{tr(agentMessage)}</strong></div>}</div><div className="agent-actions"><button className="button button-outline" onClick={refreshAgent}>{tr("Refresh status")}</button><button className="button button-primary" onClick={testAgent} disabled={agentTest === 'running'}><RefreshCw size={14} className={agentTest === 'running' ? 'spin' : ''} /> {tr("Send test ping")}</button></div></section><section className="card danger-panel"><div><span className="settings-icon danger"><RotateCcw size={18} /></span><h2>{tr("Reset demo data")}</h2><p>{tr("Restore the original GEO operations snapshot and clear all locally created assets, tasks, and statuses.")}</p></div><button className="button button-danger" onClick={reset}>{tr("Reset local demo")}</button></section><section className="about-card"><div><span className="eyebrow">{tr("ABOUT GEO OPERATIONS")}</span><h2>{tr("Original local-only product concept")}</h2><p>{tr("Built for exploring a content operations workflow: questions, knowledge, writing, validation, and owned publishing in one calm workspace. The live writing agent is opt-in per task and runs through a local proxy.") }</p></div><div className="about-facts"><span>{tr("React + TypeScript")}</span><span>{tr("Vite + Recharts")}</span><span>{tr("Lucide icons")}</span><span>{tr("Local proxy optional")}</span></div></section></div>
}

function CreateModal({ kind, state, patch, onClose, notify }: { kind: Exclude<CreateKind, null>; state: AppState; patch: (next: Partial<AppState>) => void; onClose: () => void; notify: (message: string) => void }) { const { t: tr } = useTranslation(); const titles: Record<Exclude<CreateKind, null>, string> = { knowledge: 'Create knowledge base', image: 'Create image library', keyword: 'Create keyword set', instruction: 'Create writing instruction', creation: 'Create automatic task', publishing: 'Create media task' }; const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [group, setGroup] = useState<WritingInstruction['group']>('Article'); const submit = (event: FormEvent) => { event.preventDefault(); const safeName = name.trim() || `Untitled ${titles[kind].replace('Create ', '')}`; if (kind === 'knowledge') patch({ knowledgeBases: [{ id: uid('kb'), name: safeName, description: description || 'New local knowledge source collection.', sourceCount: 0, updated: formatDate(), tone: 'Flexible', entries: [], sources: [], facts: [] }, ...state.knowledgeBases] }); if (kind === 'image') patch({ imageLibraries: [{ id: uid('img'), name: safeName, description: description || 'New local visual collection.', imageCount: 0, updated: formatDate(), style: 'Unspecified', images: [], selectedImageIds: [] }, ...state.imageLibraries] }); if (kind === 'keyword') patch({ keywordSets: [{ id: uid('ks'), name: safeName, brand: 'Example brand', questionCount: 0, date: formatDate(), tags: ['new'], prompts: [] }, ...state.keywordSets] }); if (kind === 'instruction') patch({ instructions: [{ id: uid('wi'), title: safeName, group, description: description || 'New reusable writing guidance.', updated: formatDate(), status: 'Draft' }, ...state.instructions] }); if (kind === 'creation') patch({ creationTasks: [{ id: uid('ct'), name: safeName, keyword: description || 'new content theme', questionCount: 0, writingInstruction: 'Long-form standard', titleInstruction: 'Question-led headline', knowledgeBase: 'Product Library', imageLibrary: 'Brand Kit', generated: 0, target: 10, status: 'Ready', updated: 'just now', model: 'Local simulation', localOnly: true, logs: [{ id: uid('log'), time: 'just now', message: 'Legacy quick-create task saved locally.', tone: 'info' }] }, ...state.creationTasks] }); if (kind === 'publishing') patch({ publishingTasks: [{ id: uid('pub'), name: safeName, pool: description || 'New article pool', account: 'Local account', channel: 'Website', limit: 5, deduplication: true, aiDisclosure: true, status: 'Paused', lastRun: 'Never' }, ...state.publishingTasks] }); notify(tr(`${safeName} created locally`)); onClose() }; return <Modal title={titles[kind]} onClose={onClose}><form onSubmit={submit}><div className="form-grid"><label>{tr("Name")}<span>{tr("Required for a useful local record")}</span><input autoFocus value={name} onChange={e => setName(e.target.value)} placeholder={tr("e.g. Operations planning")} /></label><label>{kind === 'instruction' ? tr('Instruction group') : kind === 'creation' ? tr('Keyword or theme') : tr('Description')}{kind === 'instruction' ? <select value={group} onChange={e => setGroup(e.target.value as WritingInstruction['group'])}><option>{tr("Article")}</option><option>{tr("Title")}</option><option>{tr("Traffic Replication")}</option></select> : <input value={description} onChange={e => setDescription(e.target.value)} placeholder={kind === 'creation' ? tr('e.g. operations planning') : tr('Short description')} />}</label></div><div className="modal-foot"><span><span className="status-dot" /> {tr("Stored in browser only")}</span><div><button type="button" className="button button-outline" onClick={onClose}>{tr("Cancel")}</button><button type="submit" className="button button-primary"><Check size={15} /> {tr("Create record")}</button></div></div></form></Modal> }

function DetailDrawer({ item, onClose }: { item: KeywordSet | Article; onClose: () => void }) { const { t: tr } = useTranslation(); const isKeyword = 'prompts' in item; return <div className="drawer-layer" onMouseDown={event => event.target === event.currentTarget && onClose()}><aside className="detail-drawer"><div className="drawer-head"><div><span className="eyebrow">{isKeyword ? tr('KEYWORD SET') : tr('ARTICLE DETAIL')}</span><h2>{tr(isKeyword ? item.name : item.title)}</h2></div><button className="icon-button" aria-label={tr("Close details")} onClick={onClose}><X size={18} /></button></div>{isKeyword ? <div className="drawer-body"><div className="drawer-summary"><div><span>{tr("Brand")}</span><strong>{tr(item.brand)}</strong></div><div><span>{tr("Questions")}</span><strong>{item.questionCount}</strong></div><div><span>{tr("Updated")}</span><strong>{tr(item.date)}</strong></div></div><section className="drawer-section"><div className="section-row"><h3>{tr("Question prompts")}</h3><span className="count-label">{item.prompts.length} {tr('samples')}</span></div><div className="prompt-list">{item.prompts.length ? item.prompts.map((prompt, index) => <div className="prompt-item" key={prompt}><span>{String(index + 1).padStart(2, '0')}</span><p>{prompt}</p></div>) : <EmptyState title={tr("No prompts yet")} text={tr("Create or import a question set in a connected workflow.")} />}</div></section></div> : <div className="drawer-body"><div className="drawer-summary"><div><span>{tr("Status")}</span><strong>{tr(item.status)}</strong></div><div><span>{tr("Model")}</span><strong>{item.model}</strong></div><div><span>{tr("Words")}</span><strong>{item.wordCount}</strong></div></div><div className="callout"><FileCheck2 size={16} /><div><strong>{tr("Publication info")}</strong><span>{tr(item.channel)} · {tr(item.date)}</span></div></div><section className="drawer-section"><h3>{tr("Content operations note")}</h3><p className="drawer-copy">{tr(`This article is a local simulated output attributed to ${item.model}. Review claims against the selected knowledge base before publishing.`)}</p></section></div>}</aside></div> }

function InteractiveDetailDrawer({ item, state, patch, onClose, onConfirm, notify }: { item: KnowledgeBase | KeywordSet | Article; state: AppState; patch: (next: Partial<AppState>) => void; onClose: () => void; onConfirm: (confirmation: { title: string; action: () => void }) => void; notify: (message: string) => void }) { const { t: tr } = useTranslation();
  const [prompt, setPrompt] = useState('')
  const [title, setTitle] = useState('prompts' in item || 'sources' in item ? '' : item.title)
  const [sourceDraft, setSourceDraft] = useState({ title: '', reference: '', excerpt: '' })
  const [factDraft, setFactDraft] = useState('')
  const [factSourceId, setFactSourceId] = useState('')
  const [editingSource, setEditingSource] = useState<string | null>(null)
  const [editingSourceDraft, setEditingSourceDraft] = useState({ title: '', reference: '', excerpt: '' })
  if ('sources' in item) {
    const knowledge = state.knowledgeBases.find(entry => entry.id === item.id) || item
    const addSource = () => { if (!sourceDraft.title.trim()) return; const source: KnowledgeSource = { id: uid('src'), title: sourceDraft.title.trim(), reference: sourceDraft.reference.trim() || 'Local note', excerpt: sourceDraft.excerpt.trim() || 'Local source excerpt awaiting review.', status: 'Review', updated: 'just now' }; patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, sources: [...entry.sources, source], sourceCount: entry.sources.length + 1, updated: 'just now' } : entry) }); setSourceDraft({ title: '', reference: '', excerpt: '' }); notify(tr('Knowledge source added locally')) }
    const saveSource = (sourceId: string) => { if (!editingSourceDraft.title.trim()) return; patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, sources: entry.sources.map(source => source.id === sourceId ? { ...source, ...editingSourceDraft, updated: 'just now' } : source), updated: 'just now' } : entry) }); setEditingSource(null); notify(tr('Knowledge source edited locally')) }
    const removeSource = (source: KnowledgeSource) => onConfirm({ title: `Delete ${source.title}?`, action: () => { patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, sources: entry.sources.filter(item => item.id !== source.id), sourceCount: Math.max(0, entry.sources.length - 1), facts: entry.facts.filter(fact => fact.sourceId !== source.id), updated: 'just now' } : entry) }); notify(tr('Knowledge source deleted locally')) } })
    const toggleSource = (source: KnowledgeSource) => { const status = source.status === 'Approved' ? 'Review' : 'Approved'; patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, sources: entry.sources.map(item => item.id === source.id ? { ...item, status, updated: 'just now' } : item) } : entry) }); notify(tr(`Knowledge source marked ${status.toLowerCase()}`)) }
    const addFact = () => { const sourceId = factSourceId || knowledge.sources[0]?.id; if (!factDraft.trim() || !sourceId) return; const fact: KnowledgeFact = { id: uid('fact'), claim: factDraft.trim(), sourceId, status: 'Review', updated: 'just now' }; patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, facts: [...entry.facts, fact], updated: 'just now' } : entry) }); setFactDraft(''); notify(tr('Knowledge fact added locally')) }
    const toggleFact = (fact: KnowledgeFact) => { const status = fact.status === 'Approved' ? 'Review' : 'Approved'; patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, facts: entry.facts.map(item => item.id === fact.id ? { ...item, status, updated: 'just now' } : item) } : entry) }); notify(tr(`Knowledge fact marked ${status.toLowerCase()}`)) }
    const removeFact = (fact: KnowledgeFact) => onConfirm({ title: `Delete fact “${fact.claim}”?`, action: () => { patch({ knowledgeBases: state.knowledgeBases.map(entry => entry.id === knowledge.id ? { ...entry, facts: entry.facts.filter(item => item.id !== fact.id), updated: 'just now' } : entry) }); notify(tr('Knowledge fact deleted locally')) } })
    return <div className="drawer-layer" onMouseDown={event => event.target === event.currentTarget && onClose()}><aside className="detail-drawer wide-drawer"><div className="drawer-head"><div><span className="eyebrow">{tr('KNOWLEDGE BASE · LOCAL')}</span><h2>{tr(knowledge.name)}</h2><p className="drawer-head-note">{tr('Sources and facts are stored in this browser and can be reviewed before the guided article flow.')}</p></div><button className="icon-button" aria-label={tr('Close details')} onClick={onClose}><X size={18} /></button></div><div className="drawer-body"><div className="drawer-summary"><div><span>{tr('Sources')}</span><strong>{knowledge.sources.length}</strong></div><div><span>{tr('Facts')}</span><strong>{knowledge.facts.length}</strong></div><div><span>{tr('Approved')}</span><strong>{knowledge.sources.filter(source => source.status === 'Approved').length + knowledge.facts.filter(fact => fact.status === 'Approved').length}</strong></div></div><div className="callout"><ShieldCheck size={16} /><div><strong>{tr('Safe local review')}</strong><span>{tr('Approve source and fact records before using them as grounding context.')}</span></div></div><section className="drawer-section"><div className="section-row"><h3>{tr('Source records')}</h3><span className="count-label">{knowledge.sources.length} {tr('sources')}</span></div><div className="inline-drawer-form"><input aria-label={tr('Source title')} value={sourceDraft.title} onChange={event => setSourceDraft({ ...sourceDraft, title: event.target.value })} placeholder={tr('Source title')} /><input aria-label={tr('Source reference')} value={sourceDraft.reference} onChange={event => setSourceDraft({ ...sourceDraft, reference: event.target.value })} placeholder={tr('Source reference')} /><textarea aria-label={tr('Source excerpt')} value={sourceDraft.excerpt} onChange={event => setSourceDraft({ ...sourceDraft, excerpt: event.target.value })} placeholder={tr('Source excerpt')} rows={2} /><button className="button button-small button-primary" onClick={addSource}><Plus size={13} /> {tr('Add source')}</button></div><div className="record-list">{knowledge.sources.map(source => <div className="knowledge-record" key={source.id}>{editingSource === source.id ? <><input value={editingSourceDraft.title} onChange={event => setEditingSourceDraft({ ...editingSourceDraft, title: event.target.value })} /><input value={editingSourceDraft.reference} onChange={event => setEditingSourceDraft({ ...editingSourceDraft, reference: event.target.value })} /><textarea value={editingSourceDraft.excerpt} onChange={event => setEditingSourceDraft({ ...editingSourceDraft, excerpt: event.target.value })} rows={2} /><div className="record-actions"><button className="button button-small button-primary" onClick={() => saveSource(source.id)}>{tr('Save')}</button><button className="button button-small button-outline" onClick={() => setEditingSource(null)}>{tr('Cancel')}</button></div></> : <><div className="knowledge-record-head"><strong>{tr(source.title)}</strong><span className={`status-pill ${source.status === 'Approved' ? 'active' : 'review'}`}>{tr(source.status)}</span></div><small>{tr(source.reference)}</small><p>{tr(source.excerpt)}</p><div className="record-actions"><button className="text-button" onClick={() => { setEditingSource(source.id); setEditingSourceDraft({ title: source.title, reference: source.reference, excerpt: source.excerpt }) }}><PenLine size={12} /> {tr('Edit')}</button><button className="text-button" onClick={() => toggleSource(source)}><Check size={12} /> {tr(source.status === 'Approved' ? 'Send to review' : 'Approve')}</button><button className="text-button danger-text" onClick={() => removeSource(source)}><Trash2 size={12} /> {tr('Delete')}</button></div></>}</div>)}</div></section><section className="drawer-section"><div className="section-row"><h3>{tr('Fact records')}</h3><span className="count-label">{knowledge.facts.length} {tr('facts')}</span></div><div className="inline-drawer-form fact-form"><textarea aria-label={tr('Fact claim')} value={factDraft} onChange={event => setFactDraft(event.target.value)} placeholder={tr('Fact claim')} rows={2} /><select aria-label={tr('Fact source')} value={factSourceId || knowledge.sources[0]?.id || ''} onChange={event => setFactSourceId(event.target.value)}>{knowledge.sources.map(source => <option value={source.id} key={source.id}>{tr(source.title)}</option>)}</select><button className="button button-small button-primary" disabled={!knowledge.sources.length} onClick={addFact}><Plus size={13} /> {tr('Add fact')}</button></div><div className="record-list">{knowledge.facts.map(fact => <div className="knowledge-record" key={fact.id}><div className="knowledge-record-head"><strong>{tr(fact.claim)}</strong><span className={`status-pill ${fact.status === 'Approved' ? 'active' : 'review'}`}>{tr(fact.status)}</span></div><small>{tr(knowledge.sources.find(source => source.id === fact.sourceId)?.title || 'Source unavailable')}</small><div className="record-actions"><button className="text-button" onClick={() => toggleFact(fact)}><Check size={12} /> {tr(fact.status === 'Approved' ? 'Send to review' : 'Approve')}</button><button className="text-button danger-text" onClick={() => removeFact(fact)}><Trash2 size={12} /> {tr('Delete')}</button></div></div>)}</div></section></div></aside></div>
  }
  if ('prompts' in item) {
    const keyword = state.keywordSets.find(entry => entry.id === item.id) || item
    const addPrompt = () => { const value = prompt.trim(); if (!value) return; patch({ keywordSets: state.keywordSets.map(entry => entry.id === keyword.id ? { ...entry, prompts: [...entry.prompts, value], questionCount: entry.questionCount + 1, date: 'just now' } : entry) }); setPrompt(''); notify(tr('Question prompt added locally')) }
    return <div className="drawer-layer" onMouseDown={event => event.target === event.currentTarget && onClose()}><aside className="detail-drawer"><div className="drawer-head"><div><span className="eyebrow">{tr("KEYWORD SET · SIMULATED")}</span><h2>{tr(keyword.name)}</h2></div><button className="icon-button" aria-label={tr("Close details")} onClick={onClose}><X size={18} /></button></div><div className="drawer-body"><div className="drawer-summary"><div><span>{tr("Brand")}</span><strong>{tr(keyword.brand)}</strong></div><div><span>{tr("Questions")}</span><strong>{keyword.questionCount}</strong></div><div><span>{tr("Updated")}</span><strong>{tr(keyword.date)}</strong></div></div><section className="drawer-section"><div className="section-row"><h3>{tr("Question prompts")}</h3><span className="count-label">{keyword.prompts.length} {tr('samples')}</span></div><div className="prompt-add"><input aria-label={tr("New question prompt")} value={prompt} onChange={event => setPrompt(event.target.value)} onKeyDown={event => event.key === 'Enter' && addPrompt()} placeholder={tr("Add a question-style prompt")} /><button className="button button-small button-primary" onClick={addPrompt}><Plus size={13} /> {tr("Add")}</button></div><div className="prompt-list">{keyword.prompts.length ? keyword.prompts.map((value, index) => <div className="prompt-item" key={`${value}-${index}`}><span>{String(index + 1).padStart(2, '0')}</span><p>{value}</p></div>) : <EmptyState title={tr("No prompts yet")} text={tr("Add the first question above.")} />}</div></section></div></aside></div>
  }
  const article = state.articles.find(entry => entry.id === item.id) || item
  const saveTitle = () => { const nextTitle = title.trim(); if (!nextTitle || nextTitle === article.title) return; patch({ articles: state.articles.map(entry => entry.id === article.id ? { ...entry, title: nextTitle } : entry) }); notify(tr('Article title saved locally')) }
  const changeStatus = (status: Article['status']) => { patch({ articles: state.articles.map(entry => entry.id === article.id ? { ...entry, status } : entry) }); notify(tr(`Article status changed to ${status}`)) }
  const deleteArticle = () => onConfirm({ title: `Delete “${article.title}”?`, action: () => { patch({ articles: state.articles.filter(entry => entry.id !== article.id) }); onClose(); notify(tr('Article deleted locally')) } })
  return <div className="drawer-layer" onMouseDown={event => event.target === event.currentTarget && onClose()}><aside className="detail-drawer"><div className="drawer-head"><div><span className="eyebrow">{tr(isRealModel(article.model) ? 'ARTICLE DETAIL · LIVE AGENT' : 'ARTICLE DETAIL · SIMULATED')}</span><h2>{tr(article.title)}</h2></div><button className="icon-button" aria-label={tr("Close details")} onClick={onClose}><X size={18} /></button></div><div className="drawer-body"><div className="drawer-summary"><div><span>{tr("Status")}</span><strong>{tr(article.status)}</strong></div><div><span>{tr("Model")}</span><strong>{tr(article.model)}</strong></div><div><span>{tr("Words")}</span><strong>{article.wordCount}</strong></div></div><section className="drawer-section edit-section"><h3>{tr("Review controls")}</h3><label className="drawer-field">{tr("Edit title")}<input value={title} onChange={event => setTitle(event.target.value)} /><button className="button button-small button-primary" onClick={saveTitle}><Check size={13} /> {tr("Save title")}</button></label><label className="drawer-field">{tr("Status")}<select value={article.status} onChange={event => changeStatus(event.target.value as Article['status'])}><option value="Draft">{tr("Draft")}</option><option value="Review">{tr("Review")}</option><option value="Published">{tr("Published")}</option><option value="Scheduled">{tr("Scheduled")}</option></select></label></section><div className="callout"><FileCheck2 size={16} /><div><strong>{tr("Publication info")}</strong><span>{tr(article.channel)} · {tr(article.date)}</span></div></div>{article.body && <section className="drawer-section"><h3>{tr(isRealModel(article.model) ? 'Live agent output' : 'Article body')}</h3><article className="article-body">{article.body.split(/\n\n+/).map((paragraph, index) => <p key={index}>{paragraph}</p>)}</article></section>}<section className="drawer-section"><h3>{tr("Content operations note")}</h3><p className="drawer-copy">{tr(isRealModel(article.model) ? `This article was generated by ${article.model} via the local proxy. Review claims against the selected knowledge base before publishing.` : `This article is a local simulated output attributed to ${article.model}. Review claims against the selected knowledge base before publishing.`)}</p></section><button className="button button-danger delete-article" onClick={deleteArticle}><Trash2 size={14} /> {tr("Delete article")}</button></div></aside></div>
}


export default App
